230	/****************************************************************************
231	 * Name: ui_build_charger
232	 *
233	 * Tab1: 4 channels x (C port + A port) = 8 ports, each showing V/A/W.
234	 * 2x2 card grid.
235	 ****************************************************************************/
236	
237	static void ui_build_charger(lv_obj_t *parent)
238	{
239	  lv_obj_t *lbl;
240	  int i;
241	
242	  /* Debug: print the REAL available tab area, then layout to fit */
243	  syslog(LOG_INFO, "Charger tab: avail %dx%d\n",
244	         lv_obj_get_width(parent), lv_obj_get_height(parent));
245	
246	  /* Layout math (480x272 screen):
247	   *  tabview 高 = 272-30(顶栏) = 242
248	   *  按钮条    = dpi/2 = 65 (dpi=130)
249	   *  内容区    = 242-65 = 177 px  -- 一屏放 2x2 卡片必须全部塞进 177px
250	   *
251	   *  标题: y 2..18 (16px)
252	   *  卡片区: 从 y=20 起, 高 157
253	   *  卡高 = (157-8)/2 = 74, 卡宽 = (480-3*8)/2 = 228
254	   *  第一行 y=20, 第二行 y=102  (20+74+8=102, 102+74=176 <= 177 OK)
255	   */
256	  const int gap = 8;
257	  const int card_w = (SCREEN_W - 3 * gap) / 2;   /* 228 */
258	  const int card_h = 74;
259	  const int start_y = 20;
260	
261	  /* Header */
262	  g_input_lbl = lv_label_create(parent);
263	  lv_label_set_text(g_input_lbl, "SW3538 Monitor");
264	  lv_obj_set_pos(g_input_lbl, 10, 2);
265	  lv_obj_set_style_text_color(g_input_lbl, COLOR_DIM, 0);
266	  lv_obj_set_style_text_font(g_input_lbl, &lv_font_montserrat_14, 0);
267	
268	  for (i = 0; i < 4; i++)
269	    {
270	      int cx = gap + (i % 2) * (card_w + gap);
271	      int cy = start_y + (i / 2) * (card_h + gap);
272	
273	      /* Card container - no border, tiny pad so content cannot overflow.
274	       * card_h=74, pad=2 => inner 70px:
275	       *   title y2  (h16) -> 18
276	       *   C line y24 (h16) -> 40
277	       *   A line y44 (h16) -> 60  (fits inside 70)
278	       */
279	      lv_obj_t *card = lv_obj_create(parent);
280	      lv_obj_set_size(card, card_w, card_h);
281	      lv_obj_set_pos(card, cx, cy);
282	      lv_obj_set_style_bg_color(card, COLOR_CARD, 0);
283	      lv_obj_set_style_radius(card, 8, 0);
284	      lv_obj_set_style_border_width(card, 0, 0);
285	      lv_obj_set_style_pad_all(card, 2, 0);
286	      lv_obj_remove_flag(card, LV_OBJ_FLAG_SCROLLABLE);
287	
288	      /* Channel name */
289	      lbl = lv_label_create(card);
290	      lv_label_set_text(lbl, g_chan[i].name);
291	      lv_obj_set_pos(lbl, 6, 2);
292	      lv_obj_set_style_text_color(lbl, COLOR_TEXT, 0);
293	      lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, 0);
294	
295	      /* C port label */
296	      g_chan_c_lbl[i] = lv_label_create(card);
297	      lv_label_set_text(g_chan_c_lbl[i], "C --");
298	      lv_obj_set_pos(g_chan_c_lbl[i], 6, 24);
299	      lv_obj_set_style_text_font(g_chan_c_lbl[i], &lv_font_montserrat_14, 0);
300	
301	      /* A port label */
302	      g_chan_a_lbl[i] = lv_label_create(card);
303	      lv_label_set_text(g_chan_a_lbl[i], "A --");
304	      lv_obj_set_pos(g_chan_a_lbl[i], 6, 44);
305	      lv_obj_set_style_text_font(g_chan_a_lbl[i], &lv_font_montserrat_14, 0);
306	
307	      /* Die temp top-right */
308	      lbl = lv_label_create(card);
309	      lv_label_set_text_fmt(lbl, "%dC", g_chan[i].die_temp);
310	      lv_obj_align(lbl, LV_ALIGN_TOP_RIGHT, -6, 4);
311	      lv_obj_set_style_text_color(lbl, COLOR_DIM, 0);
312	      lv_obj_set_style_text_font(lbl, &lv_font_montserrat_14, 0);
313	    }
314	}
