319	 * Temperature slider change callback.
320	 ****************************************************************************/
321	
322	static void ui_iron_slider_cb(lv_event_t *e)
323	{
324	  lv_obj_t *slider = lv_event_get_target(e);
325	  int target = (int)lv_slider_get_value(slider);
326	
327	  /* Snap to 5C steps */
328	  target = ((target + IRON_TEMP_STEP / 2) / IRON_TEMP_STEP) * IRON_TEMP_STEP;
329	  if (target > IRON_TEMP_MAX) target = IRON_TEMP_MAX;
330	  if (target < IRON_TEMP_MIN) target = IRON_TEMP_MIN;
331	
332	  g_iron_target = target;
333	  lv_label_set_text_fmt(g_iron_slider_lbl, "> %d°C", target);
334	  lv_slider_set_value(slider, target, LV_ANIM_OFF);
335	}
