704	/****************************************************************************
705	 * Name: ui_command_execute
706	 *
707	 * Parse a command string and execute it on the simulated device.
708	 ****************************************************************************/
709	
710	static void ui_command_execute(const char *cmd)
711	{
712	  char buf[64];
713	  int temp;
714	
715	  /* Normalize: lowercase, trim spaces */
716	  strncpy(buf, cmd, sizeof(buf) - 1);
717	  buf[sizeof(buf) - 1] = '\0';
718	
719	  /* Remove common prefixes: "hi vela" / "hello" / "set" etc */
720	  if (strstr(buf, "iron") != NULL || strstr(buf, "temp") != NULL)
721	    {
722	      /* Extract temperature value via sscanf on digits */
723	      char *p = buf;
724	      int found = 0;
725	      while (*p)
726	        {
727	          if (*p >= '0' && *p <= '9')
728	            {
729	              temp = atoi(p);
730	              /* validate range */
731	              if (temp >= IRON_TEMP_MIN && temp <= IRON_TEMP_MAX)
732	                {
733	                  g_iron_target = temp;
734	                  lv_label_set_text_fmt(g_iron_slider_lbl, "> %d°C", temp);
735	                  lv_slider_set_value(g_iron_slider, temp, LV_ANIM_OFF);
736	                  lv_label_set_text_fmt(g_ai_chat_lbl,
737	                                        "Iron temp set to %dC", temp);
738	                  found = 1;
739	                }
740	              break;
741	            }
742	          p++;
743	        }
744	      if (!found)
745	        {
746	          lv_label_set_text(g_ai_chat_lbl, "I need a temp value");
747	        }
748	    }
749	  else if (strstr(buf, "on") != NULL || strstr(buf, "heat") != NULL)
750	    {
751	      g_iron_on = true;
752	      lv_label_set_text(g_ai_chat_lbl, "Iron heating ON");
753	    }
754	  else if (strstr(buf, "off") != NULL || strstr(buf, "stop") != NULL)
755	    {
756	      g_iron_on = false;
757	      lv_label_set_text(g_ai_chat_lbl, "Iron OFF");
758	    }
759	  else if (strstr(buf, "hello") != NULL || strstr(buf, "hi") != NULL)
760	    {
761	      lv_label_set_text(g_ai_chat_lbl, "Hello! I can set the iron temp.");
762	    }
763	  else
764	    {
765	      lv_label_set_text(g_ai_chat_lbl, "Sorry, not understood");
766	    }
767	}
