786	/****************************************************************************
787	 * Name: ui_ai_drag_cb
788	 *
789	 * Drag the floating AI icon while pressed. Updates its absolute pos,
790	 * clamped to screen bounds.
791	 ****************************************************************************/
792	
793	static void ui_ai_drag_cb(lv_event_t *e)
794	{
795	  lv_obj_t *btn = lv_event_get_target(e);
796	  lv_indev_t *indev = lv_event_get_indev(e);
797	  lv_point_t p;
798	
799	  if (indev == NULL)
800	    {
801	      return;
802	    }
803	
804	  lv_indev_get_point(indev, &p);
805	
806	  /* Mark as dragged if moved more than a few px from press point */
807	  if (!g_ai_dragged &&
808	      (abs(p.x - g_ai_press_x) > 8 || abs(p.y - g_ai_press_y) > 8))
809	    {
810	      g_ai_dragged = true;
811	    }
812	
813	  lv_obj_set_pos(btn,
814	                 p.x - AI_BTN_SIZE / 2,
815	                 p.y - AI_BTN_SIZE / 2);
816	
817	  /* Clamp to screen */
818	  if (lv_obj_get_x(btn) < 0)
819	    {
820	      lv_obj_set_x(btn, 0);
821	    }
822	  else if (lv_obj_get_x(btn) > SCREEN_W - AI_BTN_SIZE)
823	    {
824	      lv_obj_set_x(btn, SCREEN_W - AI_BTN_SIZE);
825	    }
826	
827	  if (lv_obj_get_y(btn) < 0)
828	    {
829	      lv_obj_set_y(btn, 0);
830	    }
831	  else if (lv_obj_get_y(btn) > SCREEN_H - AI_BTN_SIZE)
832	    {
833	      lv_obj_set_y(btn, SCREEN_H - AI_BTN_SIZE);
834	    }
835	}
