859	 *
860	 * Toggle AI panel open/closed.
861	 ****************************************************************************/
862	
863	static void ui_ai_toggle_cb(lv_event_t *e)
864	{
865	  /* After a drag, ignore this click (it was a move, not a tap) */
866	  if (g_ai_dragged)
867	    {
868	      g_ai_dragged = false;
869	      return;
870	    }
871	
872	  if (g_ai_state == AI_STATE_CLOSED)
873	    {
874	      lv_obj_remove_flag(g_ai_panel, LV_OBJ_FLAG_HIDDEN);
875	      lv_obj_remove_flag(g_ai_mask, LV_OBJ_FLAG_HIDDEN);
876	      g_ai_state = AI_STATE_OPEN;
877	    }
878	  else
879	    {
880	      lv_obj_add_flag(g_ai_panel, LV_OBJ_FLAG_HIDDEN);
881	      lv_obj_add_flag(g_ai_mask, LV_OBJ_FLAG_HIDDEN);
882	      lv_obj_add_flag(g_ai_keyboard, LV_OBJ_FLAG_HIDDEN);
883	      g_ai_state = AI_STATE_CLOSED;
884	    }
885	  (void)e;
886	}
