1040	
1041	  if (amp > 0.01f)
1042	    {
1043	      g_chan[0].c_proto = ch1_proto;
1044	      g_chan[0].c_volt  = volt;
1045	      g_chan[0].c_amp   = amp;
1046	      g_chan[0].c_watt  = volt * amp;
1047	    }
1048	  else
1049	    {
1050	      g_chan[0].c_proto = "IDLE";
1051	      g_chan[0].c_volt  = 0.0f;
1052	      g_chan[0].c_amp   = 0.0f;
1053	      g_chan[0].c_watt  = 0.0f;
