1118	/****************************************************************************
1119	 * Name: cs_ui_data_tick
1120	 *
1121	 * Simulate data changes. Called periodically.
1122	 ****************************************************************************/
1123	
1124	void cs_ui_data_tick(void)
1125	{
1126	  static int tick = 0;
1127	  int i;
1128	
1129	  tick++;
1130	
1131	  /* Clock: advance 1 min every 60 ticks (tick = 1s) */
1132	  g_clock_min++;
1133	  if (g_clock_min >= 60)
1134	    {
1135	      g_clock_min = 0;
1136	      g_clock_hour = (g_clock_hour + 1) % 24;
1137	    }
1138	
1139	  lv_label_set_text_fmt(g_lbl_time, "%02d:%02d", g_clock_hour, g_clock_min);
1140	  lv_label_set_text_fmt(g_info_clock_lbl, "%02d:%02d", g_clock_hour, g_clock_min);
1141	
1142	  /* Update charger port labels.
1143	   * Only channel 0 C-port carries real SW3538 data (fed by main).
1144	   * No simulated fluctuation: everything not backed by real data
1145	   * shows "N/A".
1146	   */
1147	  for (i = 0; i < 4; i++)
1148	    {
1149	      if (strcmp(g_chan[i].c_proto, "IDLE") != 0)
1150	        {
1151	          lv_label_set_text_fmt(g_chan_c_lbl[i],
1152	                                "C %s %.1fV %.2fA %.1fW",
1153	                                g_chan[i].c_proto, g_chan[i].c_volt,
1154	                                g_chan[i].c_amp, g_chan[i].c_watt);
1155	        }
1156	      else
1157	        {
1158	          lv_label_set_text_fmt(g_chan_c_lbl[i], "C %s --", g_chan[i].c_proto);
1159	        }
1160	
1161	      if (strcmp(g_chan[i].a_proto, "IDLE") != 0)
1162	        {
1163	          lv_label_set_text_fmt(g_chan_a_lbl[i],
1164	                                "A %s %.1fV %.2fA %.1fW",
1165	                                g_chan[i].a_proto, g_chan[i].a_volt,
1166	                                g_chan[i].a_amp, g_chan[i].a_watt);
1167	        }
1168	      else
1169	        {
1170	          lv_label_set_text_fmt(g_chan_a_lbl[i], "A %s --", g_chan[i].a_proto);
1171	        }
1172	    }
1173	
1174	  /* Iron display: values updated from real hardware via
1175	   * cs_ui_set_iron_real(). Here we only render + advance charts.
1176	   */
1177	  lv_label_set_text_fmt(g_iron_temp_lbl, "%d", g_iron_temp);
1178	  lv_label_set_text_fmt(g_iron_pwr_lbl, "%.0f%%", (float)g_iron_power);
1179	
1180	  /* Status: heating (red) vs standby/off (gray). If heating and within
1181	   * ~5C of target, treat as "ready" (green). */
1182	  if (!g_iron_on)
1183	    {
1184	      lv_label_set_text(g_iron_status_lbl, "STANDBY");
1185	      lv_obj_set_style_text_color(g_iron_status_lbl, COLOR_DIM, 0);
1186	    }
1187	  else if (abs(g_iron_target - g_iron_temp) <= 5)
1188	    {
1189	      lv_label_set_text(g_iron_status_lbl, "READY");
1190	      lv_obj_set_style_text_color(g_iron_status_lbl, COLOR_OK, 0);
1191	    }
1192	  else
1193	    {
1194	      lv_label_set_text(g_iron_status_lbl, "HEATING");
1195	      lv_obj_set_style_text_color(g_iron_status_lbl, COLOR_HEAT, 0);
1196	    }
1197	
1198	  /* Slider label shows target */
1199	  lv_label_set_text_fmt(g_iron_slider_lbl, "> %d°C", g_iron_target);
1200	
1201	  /* Power ring: ring shows power %; center big temp already set above */
1202	  lv_arc_set_value(g_iron_pwr_arc, g_iron_power);
1203	  lv_label_set_text_fmt(g_iron_pwr_lbl, "%d%%", g_iron_power);
1204	}
