          lv_obj_set_style_bg_color(g_iron_preset_btn[i], COLOR_IRON_ACCENT, 0);
          lv_obj_set_style_text_color(lv_obj_get_child(g_iron_preset_btn[i], 0),
                                      COLOR_IRON_BG, 0);
        }
      else
