          lv_obj_set_style_bg_color(g_iron_preset_btn[i], COLOR_IRON_PANEL2, 0);
          lv_obj_set_style_text_color(lv_obj_get_child(g_iron_preset_btn[i], 0),
                                      COLOR_IRON_TEXT, 0);
        }
    }
}

