170	/****************************************************************************
171	 * Public Functions
172	 ****************************************************************************/
173	
174	/****************************************************************************
175	 * Name: sw3538_init
176	 *
177	 * Bind to an I2C bus and do a quick link probe.
178	 ****************************************************************************/
179	
180	int sw3538_init(int bus)
181	{
182	  uint8_t proto;
183	
184	  if (bus < 0)
185	    {
186	      bus = 0;
187	    }
188	
189	  g_i2c = stm32_i2cbus_initialize(bus);
190	  if (g_i2c == NULL)
191	    {
192	      ierr("SW3538: failed to init I2C bus %d\n", bus);
193	      return -ENODEV;
194	    }
195	
196	  memset(&g_status, 0, sizeof(g_status));
197	
198	  /* Link probe: read protocol register */
199	  if (sw3538_read_regs(SW3538_REG_PROTO, &proto, 1) < 0)
200	    {
201	      ierr("SW3538: no ACK from device at 0x%02x (check pin21 PSET pull-up)\n",
202	           SW3538_ADDR);
203	      return -ENXIO;
204	    }
205	
206	  iinfo("SW3538: found at 0x%02x on bus %d\n", SW3538_ADDR, bus);
207	  return OK;
208	}
209	
210	/****************************************************************************
211	 * Name: sw3538_read_status
212	 *
213	 * Read output voltage (V), C/A currents (A) and fast-charge protocol.
214	 * Returns 0 on success, negative errno on failure.
215	 ****************************************************************************/
216	
217	int sw3538_read_status(FAR struct sw3538_status_s *st)
218	{
219	  uint32_t code;
220	  uint8_t proto = 0;
221	  int ret;
222	
223	  if (st == NULL)
224	    {
225	      return -EINVAL;
226	    }
227	
228	  /* Protocol register also acts as link probe */
229	  ret = sw3538_read_regs(SW3538_REG_PROTO, &proto, 1);
230	  if (ret < 0)
231	    {
232	      return ret;
233	    }
234	
235	  /* Output voltage (VOUT, 6mV/bit) */
236	  code = sw3538_adc_code(ADC_CH_VOUT);
237	  g_status.vout_mv = (uint16_t)(code * 6u);
238	
239	  /* C port current (2.5mA/bit) */
240	  code = sw3538_adc_code(ADC_CH_IC);
241	  g_status.ic_ma = (uint16_t)(code * 25u / 10u);
242	
243	  /* A port current (2.5mA/bit) */
244	  code = sw3538_adc_code(ADC_CH_IA);
245	  g_status.ia_ma = (uint16_t)(code * 25u / 10u);
246	
247	  /* Fast-charge protocol: bits3-0 of Reg0x09 */
248	  g_status.proto = proto & 0x0F;
249	
250	  *st = g_status;
251	  return OK;
252	}
253	
254	/****************************************************************************
255	 * Name: sw3538_proto_name
256	 *
257	 * Return a human-readable protocol name.
258	 ****************************************************************************/
259	
260	const char *sw3538_proto_name(uint8_t proto)
261	{
262	  switch (proto)
263	    {
264	      case 0:  return "NONE";
265	      case 1:  return "QC2.0";
266	      case 2:  return "QC3.0";
267	      case 3:  return "QC3+";
268	      case 4:  return "FCP";
269	      case 5:  return "SCP";
270	      case 6:  return "PD";
271	      case 7:  return "PD-PPS";
272	      case 8:  return "PE1.1";
273	      case 9:  return "PE2.0";
274	      case 10: return "VOOC1";
275	      case 11: return "VOOC4";
276	      case 13: return "SFCP";
277	      case 14: return "AFC";
278	      case 15: return "TFCP";
279	      default: return "?";
280	    }
281	}
