1	/****************************************************************************
2	 * Contest 2026 team 008 - charging station main
3	 *
4	 * Entry point: initializes LVGL, display and touchscreen, then
5	 * enters the LVGL event loop with the charging station UI.
6	 * Reads SW3538 (I2C4) for real channel-1 data every ~500ms.
7	 ****************************************************************************/
8	
9	#include <nuttx/config.h>
10	
11	#include <stdio.h>
12	#include <stdlib.h>
13	#include <string.h>
14	#include <syslog.h>
15	#include <unistd.h>
16	
17	#include <lvgl/lvgl.h>
18	
19	#include "charging_station_ui.h"
20	#include "sw3538.h"
21	#include "iron.h"
22	
23	/****************************************************************************
24	 * Pre-processor Definitions
25	 ****************************************************************************/
26	
27	#define SW3538_I2C_BUS      4    /* I2C4 (D14=SDA/PD13, D15=SCL/PD12) */
28	
29	/****************************************************************************
30	 * Private Data
31	 ****************************************************************************/
32	
33	static bool g_sw3538_ok = false;
34	
35	/****************************************************************************
36	 * Private Functions
37	 ****************************************************************************/
38	
39	/****************************************************************************
40	 * Name: sw3538_poll
41	 *
42	 * Read SW3538 and push real data into UI channel 1.
43	 * On failure, mark channel idle but keep the app running.
44	 ****************************************************************************/
45	
46	static void sw3538_poll(void)
47	{
48	  struct sw3538_status_s st;
49	  int ret;
50	
51	  if (!g_sw3538_ok)
52	    {
53	      return;
54	    }
55	
56	  ret = sw3538_read_status(&st);
57	  if (ret < 0)
58	    {
59	      /* I2C glitch during charging - keep last display, just mark once */
60	      cs_ui_set_ch1_online(false);
61	      return;
62	    }
63	
64	  /* Feed UI: both ports of channel 1. Voltage read applies to the
65	   * active port; each port's current decides idle/active. */
66	  cs_ui_set_ch1_ports((float)st.vout_mv / 1000.0f,
67	                      (float)st.ic_ma / 1000.0f,
68	                      (float)st.vout_mv / 1000.0f,
69	                      (float)st.ia_ma / 1000.0f,
70	                      sw3538_proto_name(st.proto));
71	
72	  /* Debug: show what we actually read every ~2.5s */
73	  syslog(LOG_INFO, "SW3538: Vout=%dmV Ic=%dmA Ia=%dmA proto=%d(%s)\n",
74	         st.vout_mv, st.ic_ma, st.ia_ma, st.proto,
75	         sw3538_proto_name(st.proto));
76	}
77	
78	/****************************************************************************
79	 * Name: data_timer_cb
80	 *
81	 * Periodically refresh simulated data + real SW3538 readings.
82	 ****************************************************************************/
83	
84	static void data_timer_cb(lv_timer_t *timer)
85	{
86	  static int slow = 0;
87	  struct iron_status_s ist;
88	
89	  cs_ui_data_tick();
90	
91	  /* Sync UI intent (target temp / heater on) into the iron module */
92	  iron_set_target(cs_ui_get_iron_target());
93	  iron_set_heater(cs_ui_get_iron_on());
94	
95	  /* Soldering iron: PID tick every 100ms */
96	  iron_tick();
97	  iron_get_status(&ist);
98	  cs_ui_set_iron_real(ist.temp_c, ist.power_pct, ist.heating, ist.sensor_ok);
99	
100	  /* SW3538 read every 5 ticks (~500ms): 3 ADC conversions take time */
101	  if (++slow >= 5)
102	    {
103	      slow = 0;
104	      sw3538_poll();
105	    }
106	
107	  (void)timer;
108	}
109	
110	/****************************************************************************
111	 * Name: lv_nuttx_loop
112	 *
113	 * Standard LVGL poll loop.
114	 ****************************************************************************/
115	
116	static void lv_nuttx_loop(void)
117	{
118	  while (1)
119	    {
120	      uint32_t idle;
121	
122	      idle = lv_timer_handler();
123	      idle = idle ? idle : 1;
124	      usleep(idle * 1000);
125	    }
126	}
127	
128	/****************************************************************************
129	 * Public Functions
130	 ****************************************************************************/
131	
132	int main(int argc, FAR char *argv[])
133	{
134	  lv_nuttx_dsc_t info;
135	  lv_nuttx_result_t result;
136	
137	  syslog(LOG_INFO, "Charging Station starting\n");
138	
139	  /* Init soldering iron GPIO + MAX6675 probe (non-fatal) */
140	  iron_init();
141	
142	  /* Init SW3538 on I2C4 (non-fatal: UI runs on simulated data if absent) */
143	  if (sw3538_init(SW3538_I2C_BUS) < 0)
144	    {
145	      syslog(LOG_WARNING, "Charging Station: SW3538 not detected, "
146	             "channel 1 stays simulated\n");
147	    }
148	  else
149	    {
150	      g_sw3538_ok = true;
151	      syslog(LOG_INFO, "Charging Station: SW3538 ready on I2C4\n");
152	    }
153	
154	  lv_init();
155	
156	  lv_nuttx_dsc_init(&info);
157	
158	#ifdef CONFIG_LV_USE_NUTTX_LCD
159	  info.fb_path = "/dev/lcd0";
160	#endif
161	
162	  lv_nuttx_init(&info, &result);
163	
164	  if (result.disp == NULL)
165	    {
166	      syslog(LOG_ERR, "Charging Station: display init failed\n");
167	      lv_deinit();
168	      return -1;
169	    }
170	
171	  /* Build the charging station UI */
172	  if (cs_ui_init(lv_screen_active()) < 0)
173	    {
174	      syslog(LOG_ERR, "Charging Station: UI init failed\n");
175	      lv_nuttx_deinit(&result);
176	      lv_deinit();
177	      return -1;
178	    }
179	
180	  /* Start data simulation timer (100ms) */
181	  lv_timer_create(data_timer_cb, 100, NULL);
182	
183	  syslog(LOG_INFO, "Charging Station: display res=%ldx%ld\n",
184	         (long)lv_display_get_horizontal_resolution(result.disp),
185	         (long)lv_display_get_vertical_resolution(result.disp));
186	
187	  if (result.indev)
188	    {
189	      /* Speed up touch reading: 20ms poll period (faster response) */
190	      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);
191	      lv_timer_t *t = lv_indev_get_read_timer(result.indev);
192	      if (t)
193	        {
194	          lv_timer_set_period(t, 20);
195	        }
196	      syslog(LOG_INFO, "Charging Station: touchscreen registered (20ms poll)\n");
197	    }
198	  else
199	    {
200	      syslog(LOG_WARNING, "Charging Station: no touchscreen (indev NULL)\n");
201	    }
202	
203	  /* Enter the LVGL event loop */
204	  syslog(LOG_INFO, "Charging Station: entering poll loop\n");
205	  lv_nuttx_loop();
206	
207	  lv_nuttx_deinit(&result);
208	  lv_deinit();
209	  return 0;
210	}

