25	#include "sw3538.h"
26	
27	/* Board/chip provides stm32_i2cbus_initialize() - forward declare to avoid
28	 * including chip-private headers from an application directory.
29	 */
30	extern FAR struct i2c_master_s *stm32_i2cbus_initialize(int bus);
31	
32	/****************************************************************************
33	 * Pre-processor Definitions
34	 ****************************************************************************/
35	
36	#define SW3538_ADDR         0x3C   /* 7-bit slave address */
37	#define SW3538_FREQ         100000 /* 100 kHz */
38	
39	/* Registers */
40	#define SW3538_REG_PROTO    0x09   /* Fast-charge protocol indicator */
41	#define SW3538_REG_ADC_SEL  0x40   /* ADC channel select (R/W) */
42	#define SW3538_REG_ADC_LO   0x41   /* ADC result low 8 bits (R) */
43	#define SW3538_REG_ADC_HI   0x42   /* ADC result high bits (R) */
44	
45	/* ADC channels (Reg0x40 value)
46	 * NOTE: verified on real hardware - channel 1 (idis1) carries the
47	 * Type-C port current, channel 2 (idis2) the Type-A port current.
48	 * (The AI-generated F103 notes had these swapped.)
49	 */
50	#define ADC_CH_IC           1      /* Type-C port current 2.5mA/bit @5mohm */
51	#define ADC_CH_IA           2      /* Type-A port current 2.5mA/bit @5mohm */
52	#define ADC_CH_VOUT         5      /* Output voltage 6mV/bit */
53	#define ADC_CH_VOUT_CONV    11     /* Converted output voltage 1mV/bit */
54	#define ADC_CH_NTC          7      /* NTC voltage 1.2mV/bit */
55	
56	#define ADC_LO_BITS         8      /* wait for ADC conversion */
57	
58	/****************************************************************************
59	 * Private Data
60	 ****************************************************************************/
61	
62	static FAR struct i2c_master_s *g_i2c;
63	static struct sw3538_status_s g_status;
64	
65	/****************************************************************************
66	 * Private Functions
67	 ****************************************************************************/
68	
69	/****************************************************************************
70	 * Name: sw3538_read_regs
71	 *
72	 * Read len bytes from a register. Format:
73	 *   [S] [0x3C w] [reg] [Sr] [0x3C r] [data...] [P]
74	 ****************************************************************************/
75	
76	static int sw3538_read_regs(uint8_t reg, uint8_t *buf, int len)
77	{
78	  struct i2c_msg_s msg[2];
79	  uint8_t regaddr = reg;
80	  int ret;
81	
82	  if (g_i2c == NULL)
83	    {
84	      return -ENODEV;
85	    }
86	
87	  msg[0].frequency = SW3538_FREQ;
88	  msg[0].addr      = SW3538_ADDR;
89	  msg[0].flags     = 0;              /* Write register address */
90	  msg[0].buffer    = &regaddr;
91	  msg[0].length    = 1;
92	
93	  msg[1].frequency = SW3538_FREQ;
94	  msg[1].addr      = SW3538_ADDR;
95	  msg[1].flags     = I2C_M_READ;     /* Read data */
96	  msg[1].buffer    = buf;
97	  msg[1].length    = len;
98	
99	  ret = I2C_TRANSFER(g_i2c, msg, 2);
100	  return ret;
101	}
102	
103	/****************************************************************************
104	 * Name: sw3538_write_reg
105	 *
106	 * Write one byte to a register.
107	 ****************************************************************************/
108	
109	static int sw3538_write_reg(uint8_t reg, uint8_t val)
110	{
111	  struct i2c_msg_s msg;
112	  uint8_t tx[2];
113	  int ret;
114	
115	  if (g_i2c == NULL)
116	    {
117	      return -ENODEV;
118	    }
119	
120	  tx[0] = reg;
121	  tx[1] = val;
122	
123	  msg.frequency = SW3538_FREQ;
124	  msg.addr      = SW3538_ADDR;
125	  msg.flags     = 0;
126	  msg.buffer    = tx;
127	  msg.length    = 2;
128	
129	  ret = I2C_TRANSFER(g_i2c, &msg, 1);
130	  return ret;
131	}
132	
133	/****************************************************************************
134	 * Name: sw3538_adc_code
135	 *
136	 * Select an ADC channel and read the 12-bit code from 0x41/0x42.
137	 ****************************************************************************/
138	
139	static uint32_t sw3538_adc_code(uint8_t channel)
140	{
141	  uint8_t lo = 0;
142	  uint8_t hi = 0;
143	  int ret;
144	
145	  /* Select channel */
146	  ret = sw3538_write_reg(SW3538_REG_ADC_SEL, channel);
147	  if (ret < 0)
148	    {
149	      return 0;
150	    }
151	
152	  /* Wait for ADC conversion (channel select latches 0x41/0x42) */
153	  up_udelay(5000);
154	
155	  /* Read result */
156	  if (sw3538_read_regs(SW3538_REG_ADC_LO, &lo, 1) < 0)
157	    {
158	      return 0;
159	    }
160	
161	  if (sw3538_read_regs(SW3538_REG_ADC_HI, &hi, 1) < 0)
162	    {
163	      return 0;
164	    }
165	
166	  /* 12-bit: hi[3:0] << 8 | lo */
167	  return (((uint32_t)(hi & 0x0F)) << 8) | lo;
168	}
169	
170	/****************************************************************************
171	 * Public Functions
172	 ****************************************************************************/
173	
174	/****************************************************************************
175	 * Name: sw3538_init
176	 *
177	 * Bind to an I2C bus and do a quick link probe.
178	 ****************************************************************************/
179	
180	int sw3538_init(int bus)
181	{
182	  uint8_t proto;
183	
184	  if (bus < 0)
185	    {
186	      bus = 0;
187	    }
188	
189	  g_i2c = stm32_i2cbus_initialize(bus);
190	  if (g_i2c == NULL)
191	    {
192	      ierr("SW3538: failed to init I2C bus %d\n", bus);
193	      return -ENODEV;
194	    }
195	
196	  memset(&g_status, 0, sizeof(g_status));
197	
198	  /* Link probe: read protocol register */
199	  if (sw3538_read_regs(SW3538_REG_PROTO, &proto, 1) < 0)
200	    {
201	      ierr("SW3538: no ACK from device at 0x%02x (check pin21 PSET pull-up)\n",
202	           SW3538_ADDR);
203	      return -ENXIO;
204	    }
205	
206	  iinfo("SW3538: found at 0x%02x on bus %d\n", SW3538_ADDR, bus);
207	  return OK;
208	}
