244	  code = sw3538_adc_code(ADC_CH_IA);
245	  g_status.ia_ma = (uint16_t)(code * 25u / 10u);
246	
247	  /* Fast-charge protocol: bits3-0 of Reg0x09 */
248	  g_status.proto = proto & 0x0F;
249	
250	  *st = g_status;
251	  return OK;
252	}
