static void sw3538_poll(void)
{
  struct sw3538_status_s st;
  int ret;

  if (!g_sw3538_ok)
    {
      return;
    }

  ret = sw3538_read_status(&st);
  if (ret < 0)
    {
      /* I2C glitch during charging - keep last display, just mark once */
      cs_ui_set_ch1_online(false);
      return;
    }

  /* Feed UI: both ports of channel 1. Voltage read applies to the
   * active port; each port's current decides idle/active. */
  cs_ui_set_ch1_ports((float)st.vout_mv / 1000.0f,
                      (float)st.ic_ma / 1000.0f,
                      (float)st.vout_mv / 1000.0f,
                      (float)st.ia_ma / 1000.0f,
                      sw3538_proto_name(st.proto));

  /* Debug: show what we actually read every ~2.5s */
  syslog(LOG_INFO, "SW3538: Vout=%dmV Ic=%dmA Ia=%dmA proto=%d(%s)\n",
         st.vout_mv, st.ic_ma, st.ia_ma, st.proto,
         sw3538_proto_name(st.proto));
}

input.new_string:
static void sw3538_poll(void)
{
  int channel;

  for (channel = 0; channel < 4; channel++)
    {
      struct sw3538_status_s st;
      int ret;

      if (!g_sw3538_ok[channel])
        {
          continue;
        }

      ret = sw3538_read_status_channel(channel, &st);
      if (ret < 0)
        {
          syslog(LOG_WARNING, "SW3538 CH%d read failed: %d\n", channel + 1,
                 ret);
          cs_ui_set_channel_online(channel, false, false);
          continue;
        }

      cs_ui_set_channel_ports(channel, (float)st.vout_mv / 1000.0f,
                              (float)st.ic_ma / 1000.0f,
                              (float)st.vout_mv / 1000.0f,
                              (float)st.ia_ma / 1000.0f,
                              sw3538_proto_name(st.proto), st.temp_c,
                              st.temp_valid);
      cs_ui_set_channel_online(channel, (st.online & 0x02) != 0,
                               (st.online & 0x01) != 0);

      syslog(LOG_INFO, "SW3538 CH%d: Vout=%dmV Ic=%dmA Ia=%dmA "
             "temp=%s%dC proto=%d(%s)\n", channel + 1, st.vout_mv,
             st.ic_ma, st.ia_ma, st.temp_valid ? "" : "N/A ", st.temp_c,
             st.proto, sw3538_proto_name(st.proto));
    }
}

