static lv_color_t proto_color(const char *proto)
{
  if (strcmp(proto, "PD") == 0)     return BADGE_PD;
  if (strcmp(proto, "QC") == 0)     return BADGE_QC;
  if (strcmp(proto, "FCP") == 0)    return BADGE_FCP;
  if (strcmp(proto, "AFC") == 0)    return BADGE_AFC;
  return BADGE_IDLE;
}

input.new_string:
static lv_color_t proto_color(const char *proto)
{
  if (proto == NULL || strcmp(proto, "IDLE") == 0 ||
      strcmp(proto, "NONE") == 0)
    {
      return BADGE_IDLE;
    }

  if (strncmp(proto, "PD", 2) == 0) return BADGE_PD;
  if (strncmp(proto, "QC", 2) == 0) return BADGE_QC;
  if (strncmp(proto, "FCP", 3) == 0 || strncmp(proto, "SFCP", 4) == 0)
    return BADGE_FCP;
  if (strncmp(proto, "AFC", 3) == 0) return BADGE_AFC;
  return BADGE_IDLE;
}

