87	 *
88	 * Periodically refresh simulated data + real SW3538 readings.
89	 ****************************************************************************/
90	
91	static void data_timer_cb(lv_timer_t *timer)
92	{
93	  static int slow = 0;
94	  struct iron_status_s ist;
95	
96	  cs_ui_data_tick();
97	
98	  /* Sync UI intent (target temp / heater on) into the iron module */
99	  iron_set_target(cs_ui_get_iron_target());
100	  iron_set_heater(cs_ui_get_iron_on());
101	
102	  /* Soldering iron: PID tick every 100ms */
103	  iron_tick();
104	  iron_get_status(&ist);
105	  cs_ui_set_iron_real(ist.temp_c, ist.power_pct, ist.heating, ist.sensor_ok);
106	
107	  /* SW3538 read every 5 ticks (~500ms): 3 ADC conversions take time */
108	  if (++slow >= 5)
109	    {
110	      slow = 0;
111	      sw3538_poll();
112	    }
113	
114	  (void)timer;
115	}
