1	/****************************************************************************
2	 * Contest 2026 team 008 - soldering iron module
3	 *
4	 * MAX6675 K-thermocouple reader over software SPI (bit-bang GPIO),
5	 * software PWM heater control and a simple PID loop.
6	 *
7	 * Wiring (Arduino headers):
8	 *   MAX6675 SCK -> D8  (PE3)
9	 *   MAX6675 CS  -> D7  (PI8)
10	 *   MAX6675 SO  -> D6  (PE6)
11	 *   Heater PWM  -> D4  (PK1) -> NPN transistor -> MOSFET -> 24V iron
12	 *
13	 * MAX6675 protocol (16-bit read):
14	 *   D15=0(dummy), D14-D3=temp(12bit, 0.25C/bit),
15	 *   D2=1 thermocouple open, D1=0, D0=tri-state
16	 ****************************************************************************/
17	
18	#include <nuttx/config.h>
19	
20	#include <stdio.h>
21	#include <stdint.h>
22	#include <stdbool.h>
23	#include <unistd.h>
24	#include <debug.h>
25	
26	#include <nuttx/arch.h>
27	#include <arch/board/board.h>
28	
29	#include "iron.h"
30	
31	/* GPIO config macros come from chip headers not on the app include
32	 * path; use explicit values via the generic stm32 API forward decls.
33	 */
34	extern int  stm32_configgpio(uint32_t cfgset);
35	extern void stm32_gpiowrite(uint32_t pinset, bool value);
36	extern bool stm32_gpioread(uint32_t pinset);
37	
38	/****************************************************************************
39	 * Pre-processor Definitions
40	 ****************************************************************************/
41	
42	/* --- GPIO pin assignments (Arduino D4/D6/D7/D8) ---
43	 * stm32_gpio.h is not on the app include path, so pinsets are built
44	 * from the documented bit layout:
45	 *   MODE bits18-19 (OUTPUT=1<<18), SPEED bits10-11 (50MHz=2<<10),
46	 *   OUTPUT_SET bit8 (0x100), PORT bits4-7 (E=4,I=8,K=10), PIN bits0-3
47	 */
48	#define GPIO_OUTPUT_VAL     (1u << 18)
49	#define GPIO_SPEED_50MHZ    (2u << 10)
50	#define GPIO_OUTPUT_SETBIT  (1u << 8)
51	
52	#define IRON_GPIO_SCK    (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
53	                          (4u << 4) | 3u)              /* D8 = PE3  */
54	#define IRON_GPIO_CS     (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
55	                          GPIO_OUTPUT_SETBIT | (8u << 4) | 8u)  /* D7 = PI8 */
56	#define IRON_GPIO_SO     ((4u << 4) | 6u)               /* D6 = PE6 input */
57	#define IRON_GPIO_HEAT   (GPIO_OUTPUT_VAL | GPIO_SPEED_50MHZ | \
58	                          (10u << 4) | 1u)             /* D4 = PK1  */
59	
60	/* --- Timing (us) --- */
61	#define IRON_SPI_HALF_PERIOD_US  2    /* ~250kHz bit clock */
62	#define IRON_TICK_MS             100  /* PID period */
63	
64	/* --- PID limits --- */
65	#define IRON_TEMP_MIN     100
66	#define IRON_TEMP_MAX     480
67	#define IRON_PWR_MAX      100.0f
68	
69	/* Software PWM: the iron module ticks every 100ms; the PWM cycle spans
70	 * IRON_PWM_TICKS ticks => 1s period (1Hz). Soldering irons have large
71	 * thermal inertia, so 1Hz duty control is fine. power% => the heater
72	 * stays ON for the first N slices of each cycle, OFF for the rest. */
73	#define IRON_PWM_TICKS       10   /* 1s cycle = 10 x 100ms slices */
74	
75	/* Derivative low-pass: limit D-term response per tick to avoid
76	 * oscillation from quantized (100ms-sampled) temperature. */
77	#define IRON_D_MAX_SLOPE     8.0f   /* max % output change from D per tick */
78	
79	/****************************************************************************
80	 * Private Data
81	 ****************************************************************************/
82	
83	static float g_temp_c      = 25.0f;
84	static int   g_target_c    = 350;
85	static bool  g_heating     = false;
86	static bool  g_sensor_ok   = false;
87	static float g_kp          = 3.0f;
88	static float g_ki          = 0.05f;
89	static float g_kd          = 1.5f;
90	static float g_power       = 0.0f;   /* 0..100 */
91	
92	/* PID state */
93	static float g_integral    = 0.0f;
94	static float g_last_error  = 0.0f;
95	
96	/* Software PWM state: counts down every tick */
97	static int   g_pwm_slice   = 0;
98	
99	/****************************************************************************
100	 * Private Functions
101	 ****************************************************************************/
102	
103	/****************************************************************************
104	 * Name: iron_spi_delay
105	 ****************************************************************************/
106	
107	static inline void iron_spi_delay(void)
108	{
109	  up_udelay(IRON_SPI_HALF_PERIOD_US);
110	}
111	
112	/****************************************************************************
113	 * Name: max6675_read
114	 *
115	 * Bit-bang a 16-bit read from the MAX6675.
116	 * Returns 16-bit raw value (D2 = thermocouple open flag).
117	 ****************************************************************************/
118	
119	static uint16_t max6675_read(void)
120	{
121	  uint16_t value = 0;
122	  int i;
123	
124	  /* CS low to start */
125	  stm32_gpiowrite(IRON_GPIO_CS, false);
126	  iron_spi_delay();
127	
128	  /* Read 16 bits, MSB first, sample on rising edge */
129	  for (i = 0; i < 16; i++)
130	    {
131	      /* SCK low -> data valid to read */
132	      stm32_gpiowrite(IRON_GPIO_SCK, false);
133	      iron_spi_delay();
134	
135	      /* Sample SO on rising edge per MAX6675: data changes on falling
136	       * edge, so read while clock is low (stable). */
137	      value = (value << 1);
138	      if (stm32_gpioread(IRON_GPIO_SO))
139	        {
140	          value |= 1;
141	        }
142	
143	      /* SCK high */
144	      stm32_gpiowrite(IRON_GPIO_SCK, true);
145	      iron_spi_delay();
146	    }
147	
148	  /* CS high to end */
149	  stm32_gpiowrite(IRON_GPIO_CS, true);
150	  iron_spi_delay();
151	
152	  return value;
153	}
154	
155	/****************************************************************************
156	 * Name: max6675_temp
157	 *
158	 * Decode 16-bit read into Celsius. Returns -1000 if thermocouple open.
159	 ****************************************************************************/
160	
161	static float max6675_temp(uint16_t raw)
162	{
163	  if (raw & 0x0004)         /* D2: thermocouple open */
164	    {
165	      return -1000.0f;
166	    }
167	
168	  /* D14-D3 = 12-bit value, 0.25 C/bit */
169	  return (float)((raw >> 3) & 0x0FFF) * 0.25f;
170	}
171	
172	/****************************************************************************
173	 * Name: iron_pid_update
174	 *
175	 * Compute heater power % from PID on temperature error.
176	 ****************************************************************************/
177	
178	static void iron_pid_update(void)
179	{
180	  float error;
181	  float p_term;
182	  float i_term;
183	  float d_term;
184	  float d_slope;
185	
186	  if (!g_heating || !g_sensor_ok)
187	    {
188	      g_power = 0.0f;
189	      g_integral = 0.0f;
190	      g_last_error = 0.0f;
191	      return;
192	    }
193	
194	  error = (float)(g_target_c) - g_temp_c;
195	
196	  /* Proportional */
197	  p_term = g_kp * error;
198	
199	  /* Integral with anti-windup */
200	  g_integral += error * (IRON_TICK_MS / 1000.0f);
201	  if (g_integral >  1000.0f) g_integral =  1000.0f;
202	  if (g_integral < -1000.0f) g_integral = -1000.0f;
203	  i_term = g_ki * g_integral;
204	
205	  /* Derivative on error change, slope-limited so a single quantized
206	   * temperature step cannot spike the output (100ms sampling noise). */
207	  d_slope = (error - g_last_error) / (IRON_TICK_MS / 1000.0f);
208	  if (d_slope >  IRON_D_MAX_SLOPE) d_slope =  IRON_D_MAX_SLOPE;
209	  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
210	  d_term = g_kd * d_slope;
211	
212	  g_last_error = error;
213	
214	  /* Sum and clamp 0..100 */
215	  g_power = p_term + i_term + d_term;
216	  if (g_power < 0.0f)   g_power = 0.0f;
217	  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
218	}
219	
220	/****************************************************************************
221	 * Name: iron_pwm_apply
222	 *
223	 * Software PWM: turn heater GPIO on/off based on power %.
224	 * Called once per tick (100ms). We split the 100ms into N slices and
225	 * keep the heater on for the first (power%) slices.
226	 ****************************************************************************/
227	
228	static void iron_pwm_apply(void)
229	{
230	  int on_slices = (int)(g_power / 100.0f * IRON_PWM_TICKS);
231	
232	  if (!g_heating || on_slices <= 0)
233	    {
234	      stm32_gpiowrite(IRON_GPIO_HEAT, false);
235	      return;
236	    }
237	
238	  if (on_slices >= IRON_PWM_TICKS)
239	    {
240	      stm32_gpiowrite(IRON_GPIO_HEAT, true);
241	      return;
242	    }
243	
244	  /* Cycle through slices */
245	  g_pwm_slice++;
246	  if (g_pwm_slice >= IRON_PWM_TICKS)
247	    {
248	      g_pwm_slice = 0;
249	    }
250	
251	  stm32_gpiowrite(IRON_GPIO_HEAT, g_pwm_slice < on_slices);
252	}
