input.old_string:
static float max6675_temp(uint16_t raw)
{
  if (raw & 0x0004)         /* D2: thermocouple open */
    {
      return -1000.0f;
    }

  /* D14-D3 = 12-bit value, 0.25 C/bit */
  return (float)((raw >> 3) & 0x0FFF) * 0.25f;
}

input.new_string:
static bool max6675_temp(uint16_t raw, FAR float *temp_c)
{
  uint16_t code;

  if (temp_c == NULL || (raw & 0x8000) != 0 || (raw & 0x0002) != 0 ||
      (raw & 0x0004) != 0)
    {
      return false;
    }

  code = (raw >> 3) & 0x0fff;
  *temp_c = (float)code * 0.25f;
  return *temp_c >= 0.0f && *temp_c <= 1023.75f;
}

