static void iron_pid_update(void)
{
  float error;
  float p_term;
  float i_term;
  float d_term;
  float d_slope;

  if (!g_heating || !g_sensor_ok)
    {
      g_power = 0.0f;
      g_integral = 0.0f;
      g_last_error = 0.0f;
      return;
    }

  error = (float)(g_target_c) - g_temp_c;

  /* Proportional */
  p_term = g_kp * error;

  /* Integral with anti-windup */
  g_integral += error * (IRON_TICK_MS / 1000.0f);
  if (g_integral >  1000.0f) g_integral =  1000.0f;
  if (g_integral < -1000.0f) g_integral = -1000.0f;
  i_term = g_ki * g_integral;

  /* Derivative on error change, slope-limited so a single quantized
   * temperature step cannot spike the output (100ms sampling noise). */
  d_slope = (error - g_last_error) / (IRON_TICK_MS / 1000.0f);
  if (d_slope >  IRON_D_MAX_SLOPE) d_slope =  IRON_D_MAX_SLOPE;
  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
  d_term = g_kd * d_slope;

  g_last_error = error;

  /* Sum and clamp 0..100 */
  g_power = p_term + i_term + d_term;
  if (g_power < 0.0f)   g_power = 0.0f;
  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
}

input.new_string:
static void iron_pid_update(float dt)
{
  float error;
  float p_term;
  float i_term;
  float d_term;
  float d_slope;
  float candidate;

  if (!g_heating || !g_sensor_ok || !g_have_sample)
    {
      g_power = 0.0f;
      g_integral = 0.0f;
      return;
    }

  error = (float)g_target_c - g_temp_c;
  p_term = g_kp * error;
  d_slope = (g_temp_c - g_last_temp_c) / dt;
  if (d_slope > IRON_D_MAX_SLOPE) d_slope = IRON_D_MAX_SLOPE;
  if (d_slope < -IRON_D_MAX_SLOPE) d_slope = -IRON_D_MAX_SLOPE;
  d_term = -g_kd * d_slope;

  /* Conditional integration: do not integrate farther into saturation. */
  candidate = p_term + g_ki * g_integral + d_term;
  if (!((candidate >= IRON_PWR_MAX && error > 0.0f) ||
        (candidate <= 0.0f && error < 0.0f)))
    {
      g_integral += error * dt;
      if (g_integral > 1000.0f) g_integral = 1000.0f;
      if (g_integral < -1000.0f) g_integral = -1000.0f;
    }

  i_term = g_ki * g_integral;
  g_power = p_term + i_term + d_term;
  if (g_power < 0.0f) g_power = 0.0f;
  if (g_power > IRON_PWR_MAX) g_power = IRON_PWR_MAX;
}

