static void ui_pid_value_refresh(struct ui_pid_value_s *value)
{
  if (value->row == 1)
    {
      lv_label_set_text_fmt(value->label, "%d.%d", value->value / 10,
                            value->value % 10);
    }
  else
    {
      lv_label_set_text_fmt(value->label, "%d", value->value);
    }
}

static void ui_pid_step_cb(lv_event_t *e)
{
  struct ui_pid_step_s *step = lv_event_get_user_data(e);
  struct ui_pid_value_s *value;
  int max;
  int increment;

  if (step == NULL || step->value == NULL)
    {
      return;
    }

  value = step->value;
  max = value->row == 1 ? 50 : 100;
  increment = value->row == 1 ? 1 : 5;
  if (step->increment)
    {
      value->value += increment;
      if (value->value > max) value->value = max;
    }
  else
    {
      value->value -= increment;
      if (value->value < 0) value->value = 0;
    }

  if (value->row == 0) g_iron_p = (float)value->value;
  else if (value->row == 1) g_iron_i = (float)value->value / 10.0f;
  else g_iron_d = (float)value->value;
  ui_pid_value_refresh(value);
}

