93	        lv_obj_set_style_text_color(ui_TextHeatgunTemp, c, LV_PART_MAIN);
94	        lv_obj_set_style_text_color(ui_HeatgunTemp, c, LV_PART_MAIN);
95	        last_heatgun_color = heatgun_color;
96	    }
97	
98	    const uint32_t soldering_seq = g_soldering_switch_off_req_seq;
99	    if (soldering_seq != handled_soldering_switch_off_seq) {
100	        lv_obj_clear_state(ui_SolderingSwitch, LV_STATE_CHECKED);
101	        handled_soldering_switch_off_seq = soldering_seq;
102	    }
103	
104	    const uint32_t heatgun_seq = g_heatgun_switch_off_req_seq;
105	    if (heatgun_seq != handled_heatgun_switch_off_seq) {
106	        lv_obj_clear_state(ui_HeatgunSwitch, LV_STATE_CHECKED);
107	        handled_heatgun_switch_off_seq = heatgun_seq;
108	    }
109	}
