135	void Soldering_PID_Compute()
136	{
137	    // 早期退出：如果焊接被禁用
138	    if (!Soldering_Enabled) {
139	        pid_state = PID_POWER_OFF;
140	        Soldering_DutyCycle = 0.0f;
141	        soldering_smoothed_duty = 0.0f;
142	        Soldering_Set_PWM(0);
143	        soldering_state.was_disabled = true;
144	        
145	        // 重置待机状态和UI，并重置防抖状态
146	        standby_state.in_standby_mode = false;
147	        standby_state.prev_raw_sleep_signal = false; 
148	        standby_state.debounced_sleep_signal = false;
149	        standby_state.last_raw_signal_change_time = millis(); 
150	        standby_state.last_processed_debounced_signal = false; 
151	
152	        if (standby_state.ui_color_changed) {
153	            // 恢复为白色（由 core0 UI 同步任务执行）
154	            request_soldering_ui_color(PID_UI_TEXT_WHITE);
155	            standby_state.ui_color_changed = false;
156	        }
157	        
158	        // 统一处理蜂鸣器停止
159	        if (buzzer_state.short_active || buzzer_state.long_active) {
160	            Buzzer_OFF();
161	            buzzer_state.short_active = buzzer_state.long_active = false;
162	        }
163	        soldering_fault_shutdown_pending = false; // 重置故障关闭状态
164	        return;
165	    }
166	    
167	    const unsigned long current_time = millis(); // 将 current_time 提前获取
168	    
169	    // --- Sleep Signal Debouncing ---
170	    const bool current_raw_sleep_signal = Soldering_Read_SLEEP();
171	    const unsigned long SLEEP_DEBOUNCE_DURATION_MS = 200; // 防抖持续时间 (可根据实际情况调整，例如 200-500ms)
172	
173	    if (current_raw_sleep_signal != standby_state.prev_raw_sleep_signal) {
174	        // 如果当前原始信号与上一次不同，更新变化时间戳
175	        standby_state.last_raw_signal_change_time = current_time;
176	    }
177	    standby_state.prev_raw_sleep_signal = current_raw_sleep_signal;
178	
179	    // 检查信号是否已稳定超过防抖持续时间
180	    if ((current_time - standby_state.last_raw_signal_change_time) > SLEEP_DEBOUNCE_DURATION_MS) {
181	        // 信号已稳定，可以更新防抖后的信号状态
182	        // 只有当防抖后的信号确实发生改变时才更新它
183	        if (standby_state.debounced_sleep_signal != current_raw_sleep_signal) {
184	            standby_state.debounced_sleep_signal = current_raw_sleep_signal;
185	        }
186	    }
187	    // 使用防抖处理后的 sleep_mode_active 进行后续判断
188	    const bool debounced_sleep_mode_active = standby_state.debounced_sleep_signal;
189	    
190	    // 检测待机状态变化 (基于防抖后的信号的边沿)
191	    if (debounced_sleep_mode_active != standby_state.last_processed_debounced_signal) {
192	        if (debounced_sleep_mode_active) {
193	            // 进入待机模式或直接进入休眠模式
194	            standby_state.standby_start_time = current_time; 
195	            standby_state.in_standby_mode = true; // 初始设置为true，如果直接休眠则后续可能调整
196	            
197	            if (SolderingStandbyTime == 0) {
198	                // 待机时间为0，直接进入休眠
199	                pid_state = PID_SLEEP;
200	                standby_state.in_standby_mode = false; // 明确不是在"等待超时"的待机状态
201	                standby_state.sleep_read_time = current_time;
202	
203	                // 设置UI为黑色（由 core0 UI 同步任务执行）
204	                request_soldering_ui_color(PID_UI_TEXT_BLACK);
205	                // 触发进入休眠的蜂鸣器短鸣
206	                if (Buzzer_Enabled && !buzzer_state.short_active && !buzzer_state.long_active) {
207	                    Buzzer_ON();
208	                    buzzer_state.start_time = current_time;
209	                    buzzer_state.short_active = true;
210	                }
211	            } else {
212	                // 进入待机状态，继续正常循环但目标温度改为待机温度
213	                pid_state = PID_POWER_OFF;  // 重新开始循环以应用待机温度
214	                // 设置UI为蓝色（由 core0 UI 同步任务执行）
215	                request_soldering_ui_color(PID_UI_TEXT_BLUE);
216	                // 触发进入待机的蜂鸣器短鸣
217	                if (Buzzer_Enabled && !buzzer_state.short_active && !buzzer_state.long_active) {
218	                    Buzzer_ON();
219	                    buzzer_state.start_time = current_time;
220	                    buzzer_state.short_active = true;
221	                }
222	            }
223	            standby_state.ui_color_changed = true;
224	        } else {
225	            // 退出待机/休眠模式，回到正常加热流程
226	            standby_state.in_standby_mode = false;
227	            pid_state = PID_POWER_OFF;
228	            // 恢复UI颜色为白色
229	            if (standby_state.ui_color_changed) {
230	                request_soldering_ui_color(PID_UI_TEXT_WHITE);
231	                standby_state.ui_color_changed = false;
232	            }
233	            // 重置温度到达提示
234	            buzzer_state.temperature_reached_played = false;
235	            // 触发退出待机/休眠的蜂鸣器短鸣
236	            if (Buzzer_Enabled && !buzzer_state.short_active && !buzzer_state.long_active) {
237	                Buzzer_ON();
238	                buzzer_state.start_time = current_time;
239	                buzzer_state.short_active = true;
240	            }
241	        }
242	        standby_state.last_processed_debounced_signal = debounced_sleep_mode_active; // 更新上次处理的防抖信号状态
243	    }
244	    
245	    // 在待机模式下检查是否需要转入休眠（注意：不管温度是否到达待机温度，计时器都不会被清空）
246	    if (standby_state.in_standby_mode && SolderingStandbyTime > 0) {
247	        const unsigned long standby_elapsed = current_time - standby_state.standby_start_time;
248	        const unsigned long standby_timeout = (unsigned long)SolderingStandbyTime * 60000UL; // 分钟转毫秒
249	        
250	        if (standby_elapsed >= standby_timeout) {
251	            pid_state = PID_SLEEP;
252	            standby_state.in_standby_mode = false; // 已进入休眠，不再是待机
253	            standby_state.sleep_read_time = current_time; // 初始化休眠读取时间
254	
255	            // 设置UI为黑色（由 core0 UI 同步任务执行）
256	            request_soldering_ui_color(PID_UI_TEXT_BLACK);
257	            standby_state.ui_color_changed = true; // 确保颜色已设置为休眠状态的颜色
258	            // 触发进入休眠的蜂鸣器短鸣
259	            if (Buzzer_Enabled && !buzzer_state.short_active && !buzzer_state.long_active) {
260	                Buzzer_ON();
261	                buzzer_state.start_time = current_time;
262	                buzzer_state.short_active = true;
263	            }
264	        }
265	    }
266	    
267	    // 检查状态变化（启用或目标温度改变）- 但不在待机模式下重置计时器
268	    if (soldering_state.was_disabled || soldering_state.last_target_temp != SolderingTargetTemp) {
269	        buzzer_state.temperature_reached_played = false;
270	        soldering_state.last_target_temp = SolderingTargetTemp;
271	
272	        // 电烙铁从禁用切到启用时，短鸣一次
273	        if (soldering_state.was_disabled && Buzzer_Enabled &&
274	            !buzzer_state.short_active && !buzzer_state.long_active) {
275	            Buzzer_ON();
276	            buzzer_state.start_time = current_time;
277	            buzzer_state.short_active = true;
278	        }
279	
280	        soldering_state.was_disabled = false;
281	    }
282	    
283	    // 蜂鸣器管理 - 优化分支预测
284	    if (buzzer_state.short_active || buzzer_state.long_active) {
285	        if (!Buzzer_Enabled) {
286	            Buzzer_OFF();
287	            buzzer_state.short_active = buzzer_state.long_active = false;
288	        } else {
289	            const unsigned long elapsed = current_time - buzzer_state.start_time;
290	            if (buzzer_state.short_active && elapsed >= 50) {
291	                Buzzer_OFF();
292	                buzzer_state.short_active = false;
293	            } else if (buzzer_state.long_active && elapsed >= 1000) {
294	                Buzzer_OFF();
295	                buzzer_state.long_active = false;
296	            }
297	        }
298	    }
299	
300	    if (soldering_fault_shutdown_pending) {
301	        const bool buzzer_active = buzzer_state.short_active || buzzer_state.long_active;
302	        if (!Buzzer_Enabled || !buzzer_active) {
303	            Soldering_Set_PWM(0);
304	            Soldering_DutyCycle = 0.0f;
305	            soldering_smoothed_duty = 0.0f;
306	            Soldering_Enabled = false;
307	            g_soldering_switch_off_req_seq++;
308	            soldering_fault_shutdown_pending = false;
309	        }
310	        return;
311	    }
312	    
313	    // 主状态机 - 待机模式复用正常循环
314	    switch (pid_state) {
315	        case PID_POWER_OFF:
316	            Soldering_Set_PWM(0);
317	            state_start_time = current_time;
318	            pid_state = PID_WAIT_STABLE;
319	            break;
320	            
321	        case PID_WAIT_STABLE:
322	            // 内联时间检查以减少函数调用开销
323	            if (current_time - state_start_time >= 200) {
324	                pid_state = PID_READ_TEMP;
325	            }
326	            break;
327	            
328	        case PID_READ_TEMP: {
329	            // 使用块作用域减少变量生命周期
330	            uint8_t sensor_status = 0;
331	            int current_temp = 0;
332	            
333	            // SPI 总线互斥保护温度读取
334	            if (MAX6675_TryLockBus()) {
335	                sensor_status = MAX6675_Read_Soldering_Status();
336	                
337	                if (sensor_status == 0) {
338	                    current_temp = (int)MAX6675_Read_Soldering_Temperature();
339	                    MAX6675_NotifySolderingPIDRead();
340	                }
341	                MAX6675_UnlockBus();
342	            } else {
343	                // 如果互斥锁被占用，使用上次读取的温度值
344	                sensor_status = 0; // 假设传感器正常
345	                current_temp = Soldering_Temp; // 使用上次的温度值
346	            }
347	            
348	            if (sensor_status != 0) {
349	                if (!soldering_fault_shutdown_pending) {
350	                    Soldering_DutyCycle = 0.0f;
351	                    Soldering_Set_PWM(0);
352	                    pid_state = PID_POWER_OFF;
353	
354	                    if (Buzzer_Enabled && !buzzer_state.long_active && !buzzer_state.short_active) {
355	                        Buzzer_ON();
356	                        buzzer_state.start_time = current_time;
357	                        buzzer_state.long_active = true;
358	                    }
359	                    soldering_fault_shutdown_pending = true;
360	                }
361	                return;
362	            }
363	            
364	            // 传感器正常，更新温度
365	            Soldering_Temp = current_temp;
366	            
367	            // 安全检查 - 使用常量避免重复计算
368	            const int safety_threshold = SolderingTargetTempMax + 15;
369	            if (current_temp > safety_threshold) {
370	                if (!soldering_fault_shutdown_pending) {
371	                    Soldering_DutyCycle = 0.0f;
372	                    Soldering_Set_PWM(0);
373	                    pid_state = PID_POWER_OFF;
374	
375	                    if (Buzzer_Enabled && !buzzer_state.long_active && !buzzer_state.short_active) {
376	                        Buzzer_ON();
377	                        buzzer_state.start_time = current_time;
378	                        buzzer_state.long_active = true;
379	                    }
380	                    soldering_fault_shutdown_pending = true;
381	                }
382	                return;
383	            }
384	            
385	            // 根据当前模式选择目标温度
386	            const uint16_t target_temp = standby_state.in_standby_mode ? SolderingStandbyTemp : SolderingTargetTemp;
387	
388	            // 估算升温斜率（C/s），用于接近目标时预刹车
389	            float rise_rate_c_per_s = 0.0f;
390	            if (soldering_prev_temp_time > 0 && current_time > soldering_prev_temp_time) {
391	                const float dt_s = (float)(current_time - soldering_prev_temp_time) / 1000.0f;
392	                if (dt_s > 0.02f) {
393	                    rise_rate_c_per_s = (current_temp - soldering_prev_temp) / dt_s;
394	                }
395	            }
396	            soldering_prev_temp = current_temp;
397	            soldering_prev_temp_time = current_time;
398	            
399	            // 温度到达检查 - 只在正常模式下检查（待机模式不需要提示音）
400	            if (!standby_state.in_standby_mode && 
401	                !buzzer_state.temperature_reached_played && 
402	                !buzzer_state.short_active && !buzzer_state.long_active &&
403	                abs(current_temp - (int)target_temp) <= 3) {
404	                
405	                if (Buzzer_Enabled) {
406	                    Buzzer_ON();
407	                    buzzer_state.start_time = current_time;
408	                    buzzer_state.short_active = true;
409	                }
410	                buzzer_state.temperature_reached_played = true;
411	            }
412	            
413	            // PID计算 - 减少类型转换
414	            soldering_temp_float = (float)current_temp;
415	            soldering_target_temp_float = (float)target_temp;
416	            
417	            Soldering_PID.Compute();
418	
419	            // 电烙铁联动控制：接近目标和超温时动态限制功率，抑制过冲
420	            const int signed_error = (int)target_temp - current_temp;
421	            const int temp_error = abs(signed_error);
422	            float heating_cap = (float)SolderingMaxPower;
423	            if (signed_error <= -8) {
424	                heating_cap = 0.0f;
425	            } else if (signed_error <= -4) {
426	                heating_cap = 10.0f;
427	            } else if (signed_error <= -1) {
428	                heating_cap = 20.0f;
429	            } else if (temp_error <= 8) {
430	                heating_cap = clampf(26.0f, 16.0f, (float)SolderingMaxPower);
431	            }
432	
433	            // 接近目标且升温斜率较高时提前刹车，降低首次冲顶
434	            if (signed_error > 0 && signed_error <= 14) {
435	                if (rise_rate_c_per_s >= 12.0f) {
436	                    heating_cap = clampf(heating_cap, 0.0f, 12.0f);
437	                } else if (rise_rate_c_per_s >= 8.0f) {
438	                    heating_cap = clampf(heating_cap, 0.0f, 18.0f);
439	                } else if (rise_rate_c_per_s >= 5.0f) {
440	                    heating_cap = clampf(heating_cap, 0.0f, 22.0f);
441	                }
442	            }
443	
444	            // 维持阶段若明显低于目标，给轻微功率托底，避免长期低温偏差
445	            if (signed_error >= 6 && rise_rate_c_per_s < 2.0f) {
446	                heating_cap = clampf(heating_cap, 24.0f, (float)SolderingMaxPower);
447	            }
448	
449	            // 对 PID 输出做自适应平滑 + 斜率限制，减少占空比大跳变
450	            const float raw_duty = clampf(Soldering_DutyCycle, 0.0f, heating_cap);
451	            const float pre_smooth = adaptive_smooth(soldering_smoothed_duty, raw_duty, temp_error);
452	            const float up_step =
453	                (temp_error >= (int)DutySmoothErrHigh) ? SolderingDutyStepUpHighErr :
454	                (temp_error >= (int)DutySmoothErrMid) ? SolderingDutyStepUpMidErr :
455	                (temp_error >= (int)DutySmoothErrLow) ? SolderingDutyStepUpLowErr :
456	                SolderingDutyStepUpBase;
457	            float down_step =
458	                (temp_error >= (int)DutySmoothErrHigh) ? SolderingDutyStepDownHighErr :
459	                (temp_error >= (int)DutySmoothErrMid) ? SolderingDutyStepDownMidErr :
460	                (temp_error >= (int)DutySmoothErrLow) ? SolderingDutyStepDownLowErr :
461	                SolderingDutyStepDownBase;
462	
463	            // 超温时放大下降斜率，尽快卸载功率
464	            if (signed_error <= -8) down_step += 30.0f;
465	            else if (signed_error <= -4) down_step += 20.0f;
466	            else if (signed_error <= -1) down_step += 6.0f;
467	
468	            soldering_smoothed_duty = rate_limit_step(soldering_smoothed_duty, pre_smooth, up_step, down_step);
469	            soldering_smoothed_duty = clampf(soldering_smoothed_duty, 0.0f, (float)SolderingMaxPower);
470	            Soldering_DutyCycle = soldering_smoothed_duty;
471	            
472	            // 功率控制决策
473	            if (Soldering_DutyCycle > 0.0f) {
474	                Soldering_Set_PWM(Soldering_DutyCycle);
475	                state_start_time = current_time;
476	                pid_state = PID_HEATING;
477	            } else {
478	                Soldering_Set_PWM(0);
479	                pid_state = PID_POWER_OFF;
480	            }
481	            break;
482	        }
483	        
484	        case PID_HEATING: {
485	            // 基于实时温度与目标温度的80%联动加热时长
486	            const uint16_t target_temp_for_cmp = standby_state.in_standby_mode ? SolderingStandbyTemp : SolderingTargetTemp;
487	            const uint16_t threshold_80 = (uint16_t)((target_temp_for_cmp * 8U) / 10U);
488	            const uint16_t threshold_92 = (uint16_t)((target_temp_for_cmp * 92U) / 100U);
489	            const uint16_t threshold_97 = (uint16_t)((target_temp_for_cmp * 97U) / 100U);
490	
491	            unsigned long heat_duration = 200UL;
492	            if (Soldering_Temp >= (int)threshold_97) {
493	                heat_duration = 55UL;
494	            } else if (Soldering_Temp >= (int)threshold_92) {
495	                heat_duration = 85UL;
496	            } else if (Soldering_Temp >= (int)threshold_80) {
497	                heat_duration = 100UL;
498	            }
499	
500	            if (current_time - state_start_time >= heat_duration) {
501	                pid_state = PID_POWER_OFF;
502	            }
503	            break;
504	        }
505	            
506	        case PID_SLEEP:
507	            // 休眠状态 - 关闭输出，每200ms读取一次温度用于显示
508	            Soldering_Set_PWM(0);
509	            Soldering_DutyCycle = 0.0f;
510	            soldering_smoothed_duty = 0.0f;
511	            
512	            // 每200ms读取一次温度
513	            if (current_time - standby_state.sleep_read_time >= 200) {
514	                if (MAX6675_TryLockBus()) {
515	                    if (MAX6675_Read_Soldering_Status() == 0) {
516	                        Soldering_Temp = (int)MAX6675_Read_Soldering_Temperature();
517	                        MAX6675_NotifySolderingPIDRead();
518	                    }
519	                    MAX6675_UnlockBus();
520	                }
521	                standby_state.sleep_read_time = current_time;
522	            }
523	            break;
524	    }
525	}
