529	QuickPID Heatgun_PID(&heatgun_temp_float, &Heatgun_DutyCycle, &heatgun_target_temp_float,
530	                         Heatgun_KP, Heatgun_KI, Heatgun_KD,
531	                         QuickPID::pMode::pOnErrorMeas, 
532	                         QuickPID::dMode::dOnMeas, 
533	                         QuickPID::iAwMode::iAwClamp, 
534	                         QuickPID::Action::direct);
