536	void Heatgun_PID_Compute_Init()
537	{
538	    Heatgun_PID.SetOutputLimits(0, 100);
539	    Heatgun_PID.SetSampleTimeUs(200000);
540	    Heatgun_PID.SetTunings(Heatgun_KP, Heatgun_KI, Heatgun_KD);
541	    Heatgun_PID.SetMode(QuickPID::Control::automatic);
542	
543	    bool is_initially_sleeping_low = (Heatgun_Read_SLEEP() == LOW);
544	    heatgun_sleep_state.prev_raw_sleep_signal = is_initially_sleeping_low;
545	    heatgun_sleep_state.debounced_sleep_signal_is_low = is_initially_sleeping_low;
546	    heatgun_sleep_state.last_processed_debounced_signal_is_low = is_initially_sleeping_low;
547	    heatgun_sleep_state.last_raw_signal_change_time = millis();
548	    heatgun_sleep_state.in_sleep_mode_active = is_initially_sleeping_low;
549	    heatgun_sleep_state.ui_color_changed = false;
550	
551	    // 初始化蜂鸣器状态
552	    heatgun_buzzer_state.short_active = false;
553	    heatgun_buzzer_state.long_active = false;
554	    heatgun_buzzer_state.temperature_reached_played = false;
555	
556	    // 初始化内部状态
557	    heatgun_internal_state.was_disabled = true; // 假设初始为禁用状态，首次启用时会重置蜂鸣器
558	    heatgun_internal_state.last_target_temp = HeatgunTargetTemp;
559	    request_heatgun_ui_color(PID_UI_TEXT_WHITE);
560	
561	
562	    if (is_initially_sleeping_low && Heatgun_Enabled) {
563	        heatgun_pid_state = HEATGUN_PID_SLEEP_COOLING;
564	    } else {
565	        heatgun_pid_state = HEATGUN_PID_OFF;
566	    }
567	}
