574	void Heatgun_PID_Compute()
575	{
576	    const unsigned long current_time = millis();
577	
578	    // --- 如果热风枪被禁用，则提前退出 ---
579	    if (!Heatgun_Enabled) {
580	        Heatgun_Set_PWM(0);
581	        Heatgun_Set_FAN_PWM(0); 
582	        Heatgun_DutyCycle = 0.0f;
583	        heatgun_pid_state = HEATGUN_PID_OFF;
584	
585	        if (heatgun_sleep_state.ui_color_changed) {
586	            // 恢复为白色（由 core0 UI 同步任务执行）
587	            request_heatgun_ui_color(PID_UI_TEXT_WHITE);
588	            heatgun_sleep_state.ui_color_changed = false;
589	        }
590	        heatgun_sleep_state.in_sleep_mode_active = false; 
591	        
592	        if (heatgun_buzzer_state.short_active || heatgun_buzzer_state.long_active) {
593	            Buzzer_OFF();
594	            heatgun_buzzer_state.short_active = false;
595	            heatgun_buzzer_state.long_active = false;
596	        }
597	        heatgun_buzzer_state.temperature_reached_played = false; 
598	        heatgun_internal_state.was_disabled = true; 
599	        heatgun_fault_shutdown_pending = false; // 重置故障关闭状态
600	        return;
601	    }
602	
603	    // --- 热风枪温度读取 - 每200ms读取一次，独立于状态机 ---
604	    if (current_time - heatgun_last_temp_read_time >= 200) {
605	        if (MAX6675_TryLockBus()) {
606	            Heatgun_Status = MAX6675_Read_Heatgun_Status();
607	            if (Heatgun_Status == 0) {
608	                Heatgun_Temp = (int)MAX6675_Read_Heatgun_Temperature();
609	                MAX6675_NotifyHeatgunPIDRead();
610	            }
611	            MAX6675_UnlockBus();
612	        }
613	        heatgun_last_temp_read_time = current_time;
614	    }
615	
616	    // --- 获取最新的消抖后的休眠信号 ---
617	    const bool current_raw_sleep_is_low = (Heatgun_Read_SLEEP() == LOW);
618	    if (current_raw_sleep_is_low != heatgun_sleep_state.prev_raw_sleep_signal) {
619	        heatgun_sleep_state.last_raw_signal_change_time = current_time;
620	    }
621	    heatgun_sleep_state.prev_raw_sleep_signal = current_raw_sleep_is_low;
622	
623	    if ((current_time - heatgun_sleep_state.last_raw_signal_change_time) > HEATGUN_SLEEP_DEBOUNCE_DURATION_MS) {
624	        if (heatgun_sleep_state.debounced_sleep_signal_is_low != current_raw_sleep_is_low) {
625	            heatgun_sleep_state.debounced_sleep_signal_is_low = current_raw_sleep_is_low;
626	        }
627	    }
628	    const bool debounced_sleep_is_low = heatgun_sleep_state.debounced_sleep_signal_is_low;
629	
630	    // --- 检查状态变化（启用或目标温度改变）并处理刚启用时的休眠检测 ---
631	    if (heatgun_internal_state.was_disabled) { 
632	        heatgun_buzzer_state.temperature_reached_played = false;
633	        heatgun_internal_state.last_target_temp = HeatgunTargetTemp;
634	
635	        // 热风枪从禁用切到启用时，短鸣一次
636	        if (Buzzer_Enabled && !heatgun_buzzer_state.short_active && !heatgun_buzzer_state.long_active) {
637	            Buzzer_ON();
638	            heatgun_buzzer_state.start_time = current_time;
639	            heatgun_buzzer_state.short_active = true;
640	        }
641	
642	        if (debounced_sleep_is_low) {
643	            if (heatgun_sleep_state.last_processed_debounced_signal_is_low == debounced_sleep_is_low) {
644	                 heatgun_sleep_state.last_processed_debounced_signal_is_low = !debounced_sleep_is_low;
645	            }
646	        }
647	        heatgun_internal_state.was_disabled = false; 
648	    } else if (heatgun_internal_state.last_target_temp != HeatgunTargetTemp) { 
649	        heatgun_buzzer_state.temperature_reached_played = false;
650	        heatgun_internal_state.last_target_temp = HeatgunTargetTemp;
651	    }
652	
653	    // --- 热风枪蜂鸣器管理 (通用超时) ---
654	    if (heatgun_buzzer_state.short_active || heatgun_buzzer_state.long_active) {
655	        if (!Buzzer_Enabled) { 
656	            Buzzer_OFF();
657	            heatgun_buzzer_state.short_active = false;
658	            heatgun_buzzer_state.long_active = false;
659	        } else {
660	            const unsigned long elapsed = current_time - heatgun_buzzer_state.start_time;
661	            if (heatgun_buzzer_state.short_active && elapsed >= 50) { 
662	                Buzzer_OFF();
663	                heatgun_buzzer_state.short_active = false;
664	            } else if (heatgun_buzzer_state.long_active && elapsed >= 1000) { 
665	                Buzzer_OFF();
666	                heatgun_buzzer_state.long_active = false;
667	            }
668	        }
669	    }
670	
671	    // 处理热风枪故障关闭等待状态
672	    if (heatgun_fault_shutdown_pending) {
673	        const bool buzzer_active = heatgun_buzzer_state.short_active || heatgun_buzzer_state.long_active;
674	        if (!Buzzer_Enabled || !buzzer_active) {
675	            Heatgun_Set_PWM(0);
676	            Heatgun_Set_FAN_PWM(0);
677	            Heatgun_DutyCycle = 0.0f;
678	            Heatgun_Enabled = false;
679	            g_heatgun_switch_off_req_seq++;
680	            heatgun_fault_shutdown_pending = false;
681	        }
682	        return;
683	    }
684	    
685	    // --- 休眠状态转换 (基于消抖后信号的边沿检测) ---
686	    if (debounced_sleep_is_low != heatgun_sleep_state.last_processed_debounced_signal_is_low) {
687	        if (debounced_sleep_is_low) { 
688	            heatgun_sleep_state.in_sleep_mode_active = true;
689	            heatgun_pid_state = HEATGUN_PID_SLEEP_COOLING; 
690	            Heatgun_Set_PWM(0);
691	            Heatgun_DutyCycle = 0.0f;
692	            // 风扇将在 SLEEP_COOLING 状态中根据温度设置
693	
694	            // 设置为蓝色（由 core0 UI 同步任务执行）
695	            request_heatgun_ui_color(PID_UI_TEXT_BLUE);
696	            heatgun_sleep_state.ui_color_changed = true;
697	
698	            // 进入休眠冷却蜂鸣器短鸣
699	            if (Buzzer_Enabled && !heatgun_buzzer_state.short_active && !heatgun_buzzer_state.long_active) {
700	                Buzzer_ON();
701	                heatgun_buzzer_state.start_time = current_time;
702	                heatgun_buzzer_state.short_active = true;
703	            }
704	        } else { 
705	            heatgun_sleep_state.in_sleep_mode_active = false;
706	            heatgun_pid_state = HEATGUN_PID_OFF; 
707	
708	            if (heatgun_sleep_state.ui_color_changed) { 
709	                // 恢复为白色（由 core0 UI 同步任务执行）
710	                request_heatgun_ui_color(PID_UI_TEXT_WHITE);
711	                heatgun_sleep_state.ui_color_changed = false;
712	            }
713	            // 确保所有蜂鸣器停止并重置温度到达标志
714	            if (Buzzer_Enabled && (heatgun_buzzer_state.short_active || heatgun_buzzer_state.long_active)) {
715	                 Buzzer_OFF();
716	                 heatgun_buzzer_state.short_active = false;
717	                 heatgun_buzzer_state.long_active = false;
718	            }
719	            // 退出休眠蜂鸣器短鸣
720	            if (Buzzer_Enabled && !heatgun_buzzer_state.short_active && !heatgun_buzzer_state.long_active) {
721	                Buzzer_ON();
722	                heatgun_buzzer_state.start_time = current_time;
723	                heatgun_buzzer_state.short_active = true;
724	            }
725	            heatgun_buzzer_state.temperature_reached_played = false; 
726	        }
727	        heatgun_sleep_state.last_processed_debounced_signal_is_low = debounced_sleep_is_low; 
728	    }
729	
730	    // --- 热风枪主状态机 ---
731	    switch (heatgun_pid_state) {
732	        case HEATGUN_PID_OFF:
733	            Heatgun_Set_PWM(0);
734	            Heatgun_Set_FAN_PWM(0); 
735	            Heatgun_DutyCycle = 0.0f;
736	            if (Heatgun_Enabled && !debounced_sleep_is_low && !heatgun_sleep_state.in_sleep_mode_active) {
737	                heatgun_pid_state = HEATGUN_PID_HEATING;
738	                if (heatgun_sleep_state.ui_color_changed) { 
739	                     // 恢复为白色（由 core0 UI 同步任务执行）
740	                     request_heatgun_ui_color(PID_UI_TEXT_WHITE);
741	                     heatgun_sleep_state.ui_color_changed = false;
742	                }
743	            }
744	            break;
745	
746	        case HEATGUN_PID_HEATING: {
747	            if (heatgun_sleep_state.in_sleep_mode_active) { // 被休眠信号中断
748	                heatgun_pid_state = HEATGUN_PID_SLEEP_COOLING; 
749	                // UI颜色和初始风扇已在边沿检测中处理或将在SLEEP_COOLING中处理
750	                break; 
751	            }
752	
753	            if (Heatgun_Status != 0) { 
754	                if (!heatgun_fault_shutdown_pending) {
755	                    Heatgun_Set_PWM(0);
756	                    Heatgun_DutyCycle = 0.0f;
757	                    Heatgun_Set_FAN_PWM(0);
758	                    heatgun_pid_state = HEATGUN_PID_OFF;
759	
760	                    if (Buzzer_Enabled && !heatgun_buzzer_state.long_active && !heatgun_buzzer_state.short_active) {
761	                        Buzzer_ON();
762	                        heatgun_buzzer_state.start_time = current_time;
763	                        heatgun_buzzer_state.long_active = true;
764	                    }
765	                    heatgun_fault_shutdown_pending = true;
766	                }
767	                return;
768	            }
769	
770	            if (Heatgun_Temp > (HeatgunTargetTempMax + HEATGUN_SAFETY_MAX_TEMP_OFFSET)) { 
771	                if (!heatgun_fault_shutdown_pending) {
772	                    Heatgun_Set_PWM(0);
773	                    Heatgun_DutyCycle = 0.0f;
774	                    Heatgun_Set_FAN_PWM(0);
775	                    heatgun_pid_state = HEATGUN_PID_OFF;
776	
777	                    if (Buzzer_Enabled && !heatgun_buzzer_state.long_active && !heatgun_buzzer_state.short_active) {
778	                        Buzzer_ON();
779	                        heatgun_buzzer_state.start_time = current_time;
780	                        heatgun_buzzer_state.long_active = true;
781	                    }
782	                    heatgun_fault_shutdown_pending = true;
783	                }
784	                return;
785	            }
786	
787	            if (!heatgun_sleep_state.in_sleep_mode_active &&
788	                !heatgun_buzzer_state.temperature_reached_played &&
789	                !heatgun_buzzer_state.short_active && !heatgun_buzzer_state.long_active &&
790	                abs(Heatgun_Temp - (int)HeatgunTargetTemp) <= HEATGUN_TEMP_REACHED_THRESHOLD) {
791	                
792	                if (Buzzer_Enabled) {
793	                    Buzzer_ON();
794	                    heatgun_buzzer_state.start_time = current_time;
795	                    heatgun_buzzer_state.short_active = true;
796	                }
797	                heatgun_buzzer_state.temperature_reached_played = true;
798	            }
799	            
800	            heatgun_temp_float = (float)Heatgun_Temp; 
801	            heatgun_target_temp_float = (float)HeatgunTargetTemp;
802	            Heatgun_PID.Compute(); 
803	            Heatgun_Set_PWM(Heatgun_DutyCycle);
804	            Heatgun_Set_FAN_PWM((float)HeatgunWindSpeed); 
805	            break;
806	        }
807	
808	        case HEATGUN_PID_SLEEP_COOLING: 
809	            if (!heatgun_sleep_state.in_sleep_mode_active) { // 如果在冷却时休眠信号取消
810	                heatgun_pid_state = HEATGUN_PID_OFF; 
811	                // 颜色和蜂鸣器已由边沿检测处理
812	                break;
813	            }
814	
815	            Heatgun_Set_PWM(0); 
816	            Heatgun_DutyCycle = 0.0f;
817	
818	            if (Heatgun_Temp > HEATGUN_SLEEP_COOL_DOWN_TEMP_STAGE1) { // > 150C
819	                Heatgun_Set_FAN_PWM(100.0f);
820	            } else if (Heatgun_Temp > HEATGUN_SLEEP_COOL_DOWN_TEMP_STAGE2) { // (100C, 150C]
821	                Heatgun_Set_FAN_PWM(50.0f);
822	            } else { // Temp <= 100C
823	                // 转换到 SLEEP_IDLE 状态，改变UI颜色为黑色（由 core0 UI 同步任务执行）
824	                request_heatgun_ui_color(PID_UI_TEXT_BLACK);
825	                // 根据 SLEEP_IDLE 的逻辑立即设置风扇
826	                if (Heatgun_Temp > HEATGUN_SLEEP_COOL_DOWN_TEMP_STAGE3) { // (60C, 100C]
827	                    Heatgun_Set_FAN_PWM(30.0f);
828	                } else { // Temp <= 60C
829	                    heatgun_pid_state = HEATGUN_PID_SLEEP_IDLE;
830	                    Heatgun_Set_FAN_PWM(0.0f);
831	                }
832	            }
833	            break;
834	
835	        case HEATGUN_PID_SLEEP_IDLE: 
836	             if (!heatgun_sleep_state.in_sleep_mode_active) { // 如果在空闲时休眠信号取消
837	                heatgun_pid_state = HEATGUN_PID_OFF; 
838	                // 颜色和蜂鸣器已由边沿检测处理
839	                break;
840	            }
841	            Heatgun_Set_PWM(0); 
842	            Heatgun_DutyCycle = 0.0f;
843	            break;
844	    }
845	}

