3	//系统时钟频率250MHz，PWM频率 = 250MHz / (分频器 * 计数值)
4	
5	void Backlight_Init()
6	{
7	    // 设置背光PWM引脚 - 1000Hz PWM
8	    gpio_set_function(TFT_BACKLIGHT, GPIO_FUNC_PWM);
9	    uint slice_num = pwm_gpio_to_slice_num(TFT_BACKLIGHT);
10	    uint channel = pwm_gpio_to_channel(TFT_BACKLIGHT);
11	    pwm_set_clkdiv(slice_num, 250.0); // 分频器
12	    pwm_set_wrap(slice_num, 1000);    // 最大计数值 (分辨率)
13	
14	    // 确定目标亮度值
15	    uint16_t target_brightness;
16	    if (Brightness == 0)
17	    {
18	        target_brightness = 500; // 默认亮度
19	    }
20	    else
21	    {
22	        target_brightness = Brightness * 10; // 设定亮度
23	    }
24	
25	    pwm_set_enabled(slice_num, true);
26	
27	    // 渐进增加亮度，从0开始到目标值
28	    const uint16_t step = 10;     // 每次增加的步长
29	    const uint32_t delay_ms = 10; // 每步之间的延时（毫秒）
30	
31	    for (uint16_t current_level = 0; current_level <= target_brightness; current_level += step)
32	    {
33	        // 确保不超过目标值
34	        if (current_level > target_brightness)
35	        {
36	            current_level = target_brightness;
37	        }
38	
39	        pwm_set_chan_level(slice_num, channel, current_level);
40	        delay(delay_ms); // 延时
41	
42	        // 如果已达到目标值，退出循环
43	        if (current_level == target_brightness)
44	        {
45	            break;
46	        }
47	    }
48	}
