283	int iron_init(void)
284	{
285	  /* Configure GPIO pins */
286	  stm32_configgpio(IRON_GPIO_SCK);
287	  stm32_configgpio(IRON_GPIO_CS);
288	  stm32_configgpio(IRON_GPIO_SO);
289	  stm32_configgpio(IRON_GPIO_HEAT);
290	
291	  /* Idle states: CS high, clock low, heater off */
292	  stm32_gpiowrite(IRON_GPIO_CS, true);
293	  stm32_gpiowrite(IRON_GPIO_SCK, false);
294	  stm32_gpiowrite(IRON_GPIO_HEAT, false);
295	
296	  /* Probe MAX6675 */
297	  {
298	    uint16_t raw = max6675_read();
299	    float t;
300	
301	    if (!max6675_temp(raw, &t))
302	      {
303	        iwarn("IRON: invalid MAX6675 frame (raw=0x%04x)\n", raw);
304	        g_sensor_ok = false;
305	      }
306	    else
307	      {
308	        g_temp_c = t;
309	        g_last_temp_c = t;
310	        g_have_sample = true;
311	        g_sample_age = 0.0f;
312	        g_sensor_ok = true;
313	        iinfo("IRON: MAX6675 ok, T=%.1fC (raw=0x%04x)\n", t, raw);
314	      }

