/****************************************************************************
 * Name: ui_command_execute
 *
 * Parse a command string and execute it on the simulated device.
 ****************************************************************************/

static void ui_command_execute(const char *cmd)
{
  char buf[64];
  int temp;

  /* Normalize: lowercase, trim spaces */
  strncpy(buf, cmd, sizeof(buf) - 1);
  buf[sizeof(buf) - 1] = '\0';

  /* Remove common prefixes: "hi vela" / "hello" / "set" etc */
  if (strstr(buf, "iron") != NULL || strstr(buf, "temp") != NULL)
    {
