#ifdef CONFIG_NET
/****************************************************************************
 * Name: net_poll
 *
 * Read eth0 carrier state and IPv4 address for the topbar indicator.
 * IFF_RUNNING (not IFF_UP) reflects an established link.
 ****************************************************************************/

static void net_poll(void)
{
  static char last_ip[20] = "";
  static int last_state = -1;
  struct ifreq ifr;
  char ip[20] = "0.0.0.0";
  bool carrier_up = false;
  int state;
  int sd;

  sd = socket(AF_INET, SOCK_DGRAM, 0);
  if (sd < 0)
    {
      return;
    }

  memset(&ifr, 0, sizeof(ifr));
  strlcpy(ifr.ifr_name, "eth0", IFNAMSIZ);

  if (ioctl(sd, SIOCGIFFLAGS, (unsigned long)&ifr) == 0)
    {
      carrier_up = (ifr.ifr_flags & IFF_RUNNING) != 0;
    }

  memset(&ifr, 0, sizeof(ifr));
  strlcpy(ifr.ifr_name, "eth0", IFNAMSIZ);

  if (ioctl(sd, SIOCGIFADDR, (unsigned long)&ifr) == 0)
    {
      struct sockaddr_in *sin = (struct sockaddr_in *)&ifr.ifr_addr;
      snprintf(ip, sizeof(ip), "%s", inet_ntoa(sin->sin_addr));
    }

  close(sd);

  state = (carrier_up && strcmp(ip, "0.0.0.0") != 0) ? 2 :
          (strcmp(ip, "0.0.0.0") != 0) ? 1 : 0;

  if (state != last_state || strcmp(ip, last_ip) != 0)
    {
      syslog(LOG_INFO, "NET: eth0 carrier=%d ip=%s\n", carrier_up, ip);
      strlcpy(last_ip, ip, sizeof(last_ip));
      last_state = state;
      cs_ui_set_net_status("ETH", ip, carrier_up);
    }
}
#endif

