/****************************************************************************
 * Name: net_poll
 *
 * Refresh the topbar network indicator.  Uses netdev_foreach() (device-list
 * lock only) instead of ioctl() (global net_lock) so it cannot contend with
 * the ethernet PHY polling work queue.
 ****************************************************************************/

static void net_poll(void)
{
  static char last_ip[20] = "";
  in_addr_t addr = INADDR_ANY;
  struct in_addr in;
  char ip[20];

  netdev_foreach(net_poll_cb, &addr);

  in.s_addr = addr;
  if (addr == INADDR_ANY)
    {
      snprintf(ip, sizeof(ip), "--");
    }
  else
    {
      snprintf(ip, sizeof(ip), "%s", inet_ntoa(in));
    }

  if (strcmp(ip, last_ip) != 0)
    {
      syslog(LOG_INFO, "NET: eth0 ip=%s\n", ip);
      strlcpy(last_ip, ip, sizeof(last_ip));
      cs_ui_set_net_status("ETH", ip, addr != INADDR_ANY);
    }
}
#endif

