  iron_get_status(&ist);
  cs_ui_set_iron_real(ist.temp_c, ist.power_pct, ist.heating, ist.sensor_ok);
  cs_ui_set_iron_sleep(ist.sleep_active,
                       (ist.sleep_active ? ist.target_eff_c : ist.target_c));

  /* SW3538 read every 5 ticks (~500ms): 3 ADC conversions take time */
  if (++slow >= 5)
    {
      slow = 0;
      sw3538_poll();
    }

#ifdef CONFIG_NET
  /* Network status every 10 ticks (~1s) */
  if (++netslow >= 10)
    {
      netslow = 0;
      net_poll();
    }
#endif

  (void)timer;
}

