/****************************************************************************
 * Contest 2026 team 008 - AI cloud client for the charging station
 *
 * Bridges the LVGL AI floating window to the DeepSeek chat API.
 *
 * Threading: the application runs a single-threaded LVGL superloop that also
 * drives the soldering-iron PID.  A TLS handshake plus an HTTP round trip
 * takes seconds, so the request MUST NOT run on the LVGL thread.  This module
 * spawns a detached worker thread for the network call and hands the result
 * back to the LVGL thread with lv_async_call().
 ****************************************************************************/

#include <nuttx/config.h>

#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

#include <lvgl/lvgl.h>

#include "ai_client.h"

#ifdef CONFIG_DEMOS_MIMO
#  include "mimo.h"
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Keep a few turns of history so the model can resolve references such as
 * "a bit higher" against the previous request.
 */

#define AI_HISTORY_TURNS   8
#define AI_REPLY_MAX       512
#define AI_THREAD_STACK    49152

/* The model is asked to answer with exactly one command line.  The local
 * command parser (ui_command_execute) understands these templates.
 */

#define AI_SYSTEM_PROMPT \
  "You control a soldering iron charging station. " \
  "Reply with EXACTLY ONE line, chosen from:\n" \
  "iron <N>    set soldering iron target temperature, N integer 100-480\n" \
  "heat on     turn the heater on\n" \
  "heat off    turn the heater off\n" \
  "hello       greeting or anything you cannot do\n" \
  "Examples: \"make it 320\" -> \"iron 320\"; \"stop heating\" -> \"heat off\"; " \
  "\"higher\" after setting 300 -> \"iron 350\". " \
  "Clamp out-of-range temperatures. No punctuation, no markdown, no explanation."

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct ai_history_entry_s
{
  bool  is_user;          /* true = user turn, false = assistant turn */
  char *text;
};

/* Heap payload handed to the LVGL thread through lv_async_call(). */

struct ai_reply_s
{
  char *command;          /* Parsed command line, or NULL on failure */
  char *message;          /* Text to show in the chat label */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static volatile bool g_ai_busy;
static volatile bool g_ai_ready;

static struct ai_history_entry_s g_history[AI_HISTORY_TURNS];
static int g_history_count;
static int g_history_next;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_history_add
 *
 * Append one turn to the rolling history buffer.
 ****************************************************************************/

static void ai_history_add(bool is_user, const char *text)
{
  int slot = g_history_next;
  char *copy;

  if (text == NULL)
    {
      return;
    }

  copy = strdup(text);
  if (copy == NULL)
    {
      return;
    }

  if (g_history[slot].text != NULL)
    {
      free(g_history[slot].text);
    }

  g_history[slot].is_user = is_user;
  g_history[slot].text    = copy;

  g_history_next = (slot + 1) % AI_HISTORY_TURNS;
  if (g_history_count < AI_HISTORY_TURNS)
    {
      g_history_count++;
    }
}

/****************************************************************************
 * Name: ai_history_clear
 ****************************************************************************/

static void ai_history_clear(void)
{
  int i;

  for (i = 0; i < AI_HISTORY_TURNS; i++)
    {
      if (g_history[i].text != NULL)
        {
          free(g_history[i].text);
          g_history[i].text = NULL;
        }
    }

  g_history_count = 0;
  g_history_next  = 0;
}

/****************************************************************************
 * Name: ai_deliver_cb
 *
 * Runs on the LVGL thread.  Publishes the worker result and eventually
 * executes the command that the model produced.
 ****************************************************************************/

static void ai_deliver_cb(void *arg)
{
  struct ai_reply_s *reply = (struct ai_reply_s *)arg;

  ai_reply_deliver(reply->command, reply->message);

  free(reply->command);
  free(reply->message);
  free(reply);

  g_ai_busy = false;
}

/****************************************************************************
 * Name: ai_worker
 *
 * Detached worker thread: performs the blocking HTTPS request and marshals
 * the result back to the LVGL thread.
 ****************************************************************************/

static void *ai_worker(void *arg)
{
  char *user_text = (char *)arg;
  char *command = NULL;
  char *message = NULL;
  struct ai_reply_s *reply;

  ai_llm_exchange(user_text, &command, &message);

  free(user_text);

  reply = calloc(1, sizeof(struct ai_reply_s));
  if (reply == NULL)
    {
      free(command);
      free(message);
      g_ai_busy = false;
      return NULL;
    }

  reply->command = command;
  reply->message = message;

  /* Hand the result to the LVGL thread; it owns the widgets. */

  if (lv_async_call(ai_deliver_cb, reply) != LV_RESULT_OK)
    {
      free(reply->command);
      free(reply->message);
      free(reply);
      g_ai_busy = false;
    }

  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_client_init
 ****************************************************************************/

int ai_client_init(void)
{
#ifdef CONFIG_DEMOS_MIMO
  int ret;

  ret = mimo_provider_init(MIMO_API_KEY, MIMO_API_BASE_URL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "AI: provider init failed: %d\n", ret);
      return ret;
    }

  g_ai_ready = true;
  syslog(LOG_INFO, "AI: DeepSeek client ready\n");
  return OK;
#else
  return -ENOSYS;
#endif
}

/****************************************************************************
 * Name: ai_client_is_ready
 ****************************************************************************/

bool ai_client_is_ready(void)
{
  return g_ai_ready;
}

/****************************************************************************
 * Name: ai_client_reset_history
 ****************************************************************************/

void ai_client_reset_history(void)
{
  ai_history_clear();
}

/****************************************************************************
 * Name: ai_client_request_async
 *
 * Queue one user turn.  Returns OK when the worker was started, -EBUSY when a
 * request is already in flight, -ENOSYS when the client is unavailable.
 ****************************************************************************/

int ai_client_request_async(const char *user_text)
{
  pthread_attr_t attr;
  pthread_t tid;
  char *copy;
  int ret;

  if (user_text == NULL || user_text[0] == '\0')
    {
      return -EINVAL;
    }

  if (!g_ai_ready)
    {
      return -ENOSYS;
    }

  if (g_ai_busy)
    {
      return -EBUSY;
    }

  copy = strdup(user_text);
  if (copy == NULL)
    {
      return -ENOMEM;
    }

  g_ai_busy = true;

  /* mbedTLS needs a deep stack for the handshake; keep it off the (already
   * fully committed) LVGL thread.
   */

  ret = pthread_attr_init(&attr);
  if (ret == 0)
    {
      pthread_attr_setstacksize(&attr, AI_THREAD_STACK);
      ret = pthread_create(&tid, &attr, ai_worker, copy);
      pthread_attr_destroy(&attr);
    }

  if (ret != 0)
    {
      free(copy);
      g_ai_busy = false;
      return -ret;
    }

  pthread_detach(tid);
  return OK;
}

/****************************************************************************
 * Contest 2026 team 008 - AI cloud client for the charging station
 *
 * Bridges the LVGL AI floating window to the DeepSeek chat API.
 *
 * Threading: the application runs a single-threaded LVGL superloop that also
 * drives the soldering-iron PID.  A TLS handshake plus an HTTP round trip
 * takes seconds, so the request MUST NOT run on the LVGL thread.  This module
 * spawns a detached worker thread for the network call and reports the result
 * through the callback registered with ai_client_set_complete_cb(); that
 * callback is invoked from the worker thread, so it must only marshal data
 * (for example with lv_async_call) and never touch widgets directly.
 ****************************************************************************/

#ifndef __AI_CLIENT_H
#define __AI_CLIENT_H

#include <stdbool.h>

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* Callback invoked from the worker thread when a request finishes.
 * Both strings are heap allocated and owned by the callee after return;
 * they are NULL when the request failed.
 */

typedef void (*ai_client_complete_cb_t)(char *command, char *message,
                                        void *arg);

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Initialize the DeepSeek client (wraps mimo_provider_init). */

int  ai_client_init(void);

/* True once the provider initialized successfully. */

bool ai_client_is_ready(void);

/* Register the completion callback.  Call once before the first request. */

void ai_client_set_complete_cb(ai_client_complete_cb_t cb, void *arg);

/* Queue one user turn.  Returns 0 when the worker was started, -EBUSY when a
 * request is already in flight, -ENOSYS when the client is unavailable.
 */

int  ai_client_request_async(const char *user_text);

/* Drop the multi-turn conversation history. */

void ai_client_reset_history(void);

/****************************************************************************
 * Internal - implemented by the application, called from the worker thread
 ****************************************************************************/

/* Runs the blocking HTTPS exchange.  On success *command receives the single
 * command line produced by the model and *message receives a short summary for
 * the chat window; both are heap allocated.  The application supplies this so
 * that ai_client.c stays independent of the mimo header and of the command
 * vocabulary.
 */

void ai_llm_exchange(const char *user_text, char **command, char **message);

#endif /* __AI_CLIENT_H */

/****************************************************************************
 * Contest 2026 team 008 - AI cloud client for the charging station
 *
 * Bridges the LVGL AI floating window to the DeepSeek chat API.
 *
 * Threading: the application runs a single-threaded LVGL superloop that also
 * drives the soldering-iron PID.  A TLS handshake plus an HTTP round trip
 * takes seconds, so the request MUST NOT run on the LVGL thread.  This module
 * spawns a detached worker thread for the network call and reports the result
 * through the callback registered with ai_client_set_complete_cb().
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>

#include "ai_client.h"

#ifdef CONFIG_DEMOS_MIMO
#  include "mimo.h"
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Keep a few turns of history so the model can resolve references such as
 * "a bit higher" against the previous request.
 */

#define AI_HISTORY_TURNS   8
#define AI_REPLY_MAX       512
#define AI_THREAD_STACK    49152

/* The model answers with exactly one command line.  The local command parser
 * in charging_station_ui.c understands these templates.
 */

#define AI_SYSTEM_PROMPT \
  "You control a soldering iron charging station. " \
  "Reply with EXACTLY ONE line, chosen from:\n" \
  "iron <N>    set soldering iron target temperature, N integer 100-480\n" \
  "heat on     turn the heater on\n" \
  "heat off    turn the heater off\n" \
  "hello       greeting or anything you cannot do\n" \
  "Examples: \"make it 320\" -> \"iron 320\"; \"stop heating\" -> \"heat off\"; " \
  "\"higher\" after setting 300 -> \"iron 350\". " \
  "Clamp out-of-range temperatures. No punctuation, no markdown, no explanation."

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct ai_history_entry_s
{
  bool  is_user;          /* true = user turn, false = assistant turn */
  char *text;
};

/* Argument passed to the detached worker thread. */

struct ai_worker_arg_s
{
  char *user_text;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static volatile bool g_ai_busy;
static volatile bool g_ai_ready;

static ai_client_complete_cb_t g_complete_cb;
static void *g_complete_arg;

static struct ai_history_entry_s g_history[AI_HISTORY_TURNS];
static int g_history_count;
static int g_history_next;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_history_add
 *
 * Append one turn to the rolling history buffer.
 ****************************************************************************/

static void ai_history_add(bool is_user, const char *text)
{
  int slot = g_history_next;
  char *copy;

  if (text == NULL)
    {
      return;
    }

  copy = strdup(text);
  if (copy == NULL)
    {
      return;
    }

  if (g_history[slot].text != NULL)
    {
      free(g_history[slot].text);
    }

  g_history[slot].is_user = is_user;
  g_history[slot].text    = copy;

  g_history_next = (slot + 1) % AI_HISTORY_TURNS;
  if (g_history_count < AI_HISTORY_TURNS)
    {
      g_history_count++;
    }
}

/****************************************************************************
 * Name: ai_history_clear
 ****************************************************************************/

void ai_client_reset_history(void)
{
  int i;

  for (i = 0; i < AI_HISTORY_TURNS; i++)
    {
      if (g_history[i].text != NULL)
        {
          free(g_history[i].text);
          g_history[i].text = NULL;
        }
    }

  g_history_count = 0;
  g_history_next  = 0;
}

/****************************************************************************
 * Name: ai_worker
 *
 * Detached worker thread: performs the blocking HTTPS request and reports the
 * result through the completion callback (which must not touch widgets).
 ****************************************************************************/

static void *ai_worker(void *arg)
{
  struct ai_worker_arg_s *wa = (struct ai_worker_arg_s *)arg;
  char *command = NULL;
  char *message = NULL;

  ai_llm_exchange(wa->user_text, &command, &message);

  free(wa->user_text);
  free(wa);

  if (g_complete_cb != NULL)
    {
      g_complete_cb(command, message, g_complete_arg);
    }
  else
    {
      free(command);
      free(message);
    }

  g_ai_busy = false;
  return NULL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_client_init
 ****************************************************************************/

int ai_client_init(void)
{
#ifdef CONFIG_DEMOS_MIMO
  int ret;

  ret = mimo_provider_init(MIMO_API_KEY, MIMO_API_BASE_URL);
  if (ret < 0)
    {
