/****************************************************************************
 * Name: ai_client_request_async
 *
 * Queue one user turn.  Returns 0 when the worker was started, -EBUSY when a
 * request is already in flight, -ENOSYS when the client is unavailable.
 ****************************************************************************/

int ai_client_request_async(const char *user_text)
{
  struct ai_worker_arg_s *wa;
  pthread_attr_t attr;
  pthread_t tid;
  int ret;

  if (user_text == NULL || user_text[0] == '\0')
    {
      return -EINVAL;
    }

  if (!g_ai_ready)
    {
      return -ENOSYS;
    }

  if (g_ai_busy)
    {
      return -EBUSY;
    }

  wa = calloc(1, sizeof(struct ai_worker_arg_s));
  if (wa == NULL)
    {
      return -ENOMEM;
    }

  wa->user_text = strdup(user_text);
  if (wa->user_text == NULL)
    {
      free(wa);
      return -ENOMEM;
    }

  g_ai_busy = true;

  /* mbedTLS needs a deep stack for the handshake; keep it off the (already
   * fully committed) LVGL thread.
   */

  ret = pthread_attr_init(&attr);
  if (ret == 0)
    {
      pthread_attr_setstacksize(&attr, AI_THREAD_STACK);
      ret = pthread_create(&tid, &attr, ai_worker, wa);
      pthread_attr_destroy(&attr);
    }

  if (ret != 0)
    {
      free(wa->user_text);
      free(wa);
      g_ai_busy = false;
      return -ret;
    }

  pthread_detach(tid);
  return OK;
}

/****************************************************************************
 * Name: ai_client_history_export
 *
 * Snapshot the rolling history into a mimo message array.  Implemented here
 * so the ring buffer stays private; the caller owns the array and must free
 * it with ai_client_history_free().
 ****************************************************************************/

#ifdef CONFIG_DEMOS_MIMO

int ai_client_history_export(struct mimo_message_s **msgs_out, int *count_out)
{
  struct mimo_message_s *msgs;
  int n;
  int start;
  int i;

  if (msgs_out == NULL || count_out == NULL)
    {
      return -EINVAL;
    }

  n = g_history_count;
  msgs = calloc(n > 0 ? n : 1, sizeof(struct mimo_message_s));
  if (msgs == NULL)
    {
      return -ENOMEM;
    }

  /* Walk the ring in chronological order. */

  start = (g_history_next - n + AI_HISTORY_TURNS) % AI_HISTORY_TURNS;

  for (i = 0; i < n; i++)
    {
      int slot = (start + i) % AI_HISTORY_TURNS;

      msgs[i].role    = g_history[slot].is_user ? MIMO_ROLE_USER :
                                                  MIMO_ROLE_ASSISTANT;
      msgs[i].content = strdup(g_history[slot].text != NULL ?
                               g_history[slot].text : "");
    }

  *msgs_out  = msgs;
  *count_out = n;
  return OK;
}

void ai_client_history_free(struct mimo_message_s *msgs, int count)
{
  int i;

  if (msgs == NULL)
    {
      return;
    }

  for (i = 0; i < count; i++)
    {
      if (msgs[i].content != NULL)
        {
          free(msgs[i].content);
        }
    }

  free(msgs);
}

void ai_client_history_push(bool is_user, const char *text)
{
  ai_history_add(is_user, text);
}

const char *ai_client_system_prompt(void)
{
  return AI_SYSTEM_PROMPT;
}

#endif /* CONFIG_DEMOS_MIMO */

