static void ui_command_execute(const char *cmd)
{
  char buf[64];
  char *p;
  int temp;
  int found = 0;

  /* Normalize: copy and lowercase so matching is case insensitive. */

  strncpy(buf, cmd, sizeof(buf) - 1);
  buf[sizeof(buf) - 1] = '\0';

  for (p = buf; *p != '\0'; p++)
    {
      *p = (char)tolower((unsigned char)*p);
    }

  /* Test the on/off forms first: a phrase such as "turn off the iron"
   * contains "iron" and would otherwise be captured by the temperature
   * branch below.
   */

  if (strstr(buf, "off") != NULL || strstr(buf, "stop") != NULL)
    {
      g_iron_on = false;
      lv_label_set_text(g_ai_chat_lbl, "Iron OFF");
      return;
    }

  if (strstr(buf, "heat on") != NULL)
    {
      g_iron_on = true;
      lv_label_set_text(g_ai_chat_lbl, "Iron heating ON");
      return;
    }

  if (strstr(buf, "iron") != NULL || strstr(buf, "temp") != NULL ||
      strstr(buf, "heat") != NULL)
    {
      /* Extract the first integer in the buffer. */

      for (p = buf; *p != '\0'; p++)
        {
          if (*p >= '0' && *p <= '9')
            {
              temp = atoi(p);

              if (temp >= IRON_TEMP_MIN && temp <= IRON_TEMP_MAX)
                {
                  ui_iron_set_target(temp);
                  lv_label_set_text_fmt(g_ai_chat_lbl,
                                        "Iron temp set to %dC", temp);
                  found = 1;
                }
              break;
            }
        }

      if (!found)
        {
          lv_label_set_text(g_ai_chat_lbl, "I need a temp value");
        }

      return;
    }

  if (strstr(buf, "hello") != NULL || strstr(buf, "hi") != NULL)
    {
      lv_label_set_text(g_ai_chat_lbl, "Hello! I can set the iron temp.");
      return;
    }

  lv_label_set_text(g_ai_chat_lbl, "Sorry, not understood");
}

