/****************************************************************************
 * Name: ai_llm_exchange
 *
 * Runs on the ai_client worker thread.  Performs the blocking HTTPS request
 * to DeepSeek and returns the command line plus a short summary for the chat
 * window.  Both outputs are heap allocated.
 ****************************************************************************/

#ifdef CONFIG_DEMOS_MIMO
void ai_llm_exchange(const char *user_text, char **command, char **message)
{
  struct mimo_chat_req_s req;
  struct mimo_chat_resp_s resp;
  struct mimo_message_s *msgs = NULL;
  char *cmd_dup = NULL;
  char *msg_dup = NULL;
  int count = 0;
  int ret;

  *command = NULL;
  *message = NULL;

  /* Replay the rolling history, then append this turn. */

  ai_client_history_export(&msgs, &count);
  ai_client_history_push(true, user_text);

  memset(&req, 0, sizeof(req));
  req.model         = MIMO_MODEL;
  req.system_prompt = ai_client_system_prompt();
  req.messages      = msgs;
  req.message_count = count;
  req.temperature   = 30;   /* deterministic: this is a command translator */

  memset(&resp, 0, sizeof(resp));

  ret = mimo_provider_chat(&req, &resp);
  ai_client_history_free(msgs, count);

  if (ret < 0 || resp.content == NULL)
    {
      msg_dup = strdup("AI request failed (network or API error)");
      mimo_chat_resp_free(&resp);
      *message = msg_dup;
      return;
    }

  /* The model is instructed to answer with a single command line.  Keep only
   * the first line and trim leading spaces.
   */

  {
    char *nl = strchr(resp.content, '\n');
    char *text = resp.content;

    if (nl != NULL)
      {
        *nl = '\0';
      }

    while (*text == ' ' || *text == '\t')
      {
        text++;
      }

    if (text[0] != '\0')
      {
        cmd_dup = strdup(text);
        ai_client_history_push(false, text);
        syslog(LOG_INFO, "AI: model command \"%s\"\n", text);
      }
  }

  mimo_chat_resp_free(&resp);

  if (cmd_dup == NULL)
    {
      msg_dup = strdup("AI returned an empty answer");
      *message = msg_dup;
      return;
    }

  *command = cmd_dup;
}
#else
void ai_llm_exchange(const char *user_text, char **command, char **message)
{
  (void)user_text;
  *command = NULL;
  *message = strdup("AI client not built in");
}
#endif

