/****************************************************************************
 * Name: ai_worker
 *
 * Detached worker thread: performs the blocking HTTPS request and deposits the
 * answer in the result slot.  It deliberately does not touch LVGL - the
 * application drains the slot from its own timer callback.
 ****************************************************************************/

static void *ai_worker(void *arg)
{
  struct ai_worker_arg_s *wa = (struct ai_worker_arg_s *)arg;
  char *command = NULL;
  char *message = NULL;

  ai_llm_exchange(wa->user_text, &command, &message);

  free(wa->user_text);
  free(wa);

  g_result_command = command;
  g_result_message = message;
  g_result_pending = true;

  g_ai_busy = false;
  return NULL;
}

/****************************************************************************
 * Name: ai_client_poll
 *
 * Called from the LVGL thread.  Hands over the worker's result when one is
 * ready so that every widget update happens on the LVGL thread.
 ****************************************************************************/

bool ai_client_poll(char **command, char **message)
{
  if (!g_result_pending)
    {
      return false;
    }

  *command = g_result_command;
  *message = g_result_message;

  g_result_command = NULL;
  g_result_message = NULL;
  g_result_pending = false;

  return true;
}

