{
    const char* p = buf;
    const char* end = buf + len;

    while (p < end) {
        const char* crlf = (const char*)memmem(p, (size_t)(end - p), "\r\n", 2);
        if (!crlf) return false;

        char* endptr;
        long chunk_sz = strtol(p, &endptr, 16);
        if (endptr == p || chunk_sz < 0) return false;

        while (endptr < crlf && (*endptr == ' ' || *endptr == '\t')) endptr++;
        if (endptr != crlf) return false;

        if (chunk_sz == 0) return true;

        p = crlf + 2;
        if ((size_t)(end - p) < (size_t)chunk_sz) return false;
        p += chunk_sz;
        if ((size_t)(end - p) >= 2 && p[0] == '\r' && p[1] == '\n') p += 2;
    }
    return false;
}

