/* ── Clock-safe elapsed time calculation ───────────────────── */
/* Monotonic timestamps are used so that an adjustment of the wall clock while
 * an LLM call is in flight (for example the TLS layer setting the time forward
 * so certificate validation succeeds on a board without an RTC) cannot make a
 * fast call look like a timeout. */

static inline uint32_t calc_elapsed_ms(const struct timespec* t0,
    const struct timespec* t1)
{
    int64_t sec_diff = (int64_t)t1->tv_sec - (int64_t)t0->tv_sec;
    int64_t nsec_diff = (int64_t)t1->tv_nsec - (int64_t)t0->tv_nsec;

    if (sec_diff < 0)
        {
            return 0;
        }

    /* Nanosecond borrow */
    if (nsec_diff < 0 && sec_diff > 0)
        {
            sec_diff--;
            nsec_diff += 1000000000L;
        }
    else if (nsec_diff < 0)
        {
            nsec_diff = 0;
        }

    int64_t total = sec_diff * 1000 + nsec_diff / 1000000L;
    if (total > (int64_t)UINT32_MAX)
        {
            return UINT32_MAX;
        }

    return (uint32_t)total;
}

/* Sample CLOCK_MONOTONIC.  Never fails in practice; a zeroed timestamp simply
 * yields an elapsed time of 0. */

static inline void agent_now(struct timespec* ts)
{
    if (clock_gettime(CLOCK_MONOTONIC, ts) != 0)
        {
            ts->tv_sec = 0;
            ts->tv_nsec = 0;
        }
}

